function nextValidationDesignId(){ensureValidationDesignStore();let n=1;const ids=new Set(state.validationDesigns.map(x=>x.id));while(ids.has(`VAL-DES-${String(n).padStart(3,'0')}`))n++;return `VAL-DES-${String(n).padStart(3,'0')}`}
function captureBuilderInputs(){if(route!=='builder'||!main||!state?.settings?.builderDraft)return state?.settings?.builderDraft;const d=state.settings.builderDraft;for(const el of main.querySelectorAll('[data-builder]')){const k=el.dataset.builder;if(!k)continue;d[k]=['businessPriority','dutCount','budget','prototypeQty','prototypeBuildHoursPerUnit'].includes(k)?Number(el.value):el.value;}for(const el of main.querySelectorAll('.builder-serial')){const i=Number(el.dataset.serialIndex);if(Number.isFinite(i)){ensureBuilderSerials(d);d.serialNumbers[i]=el.value.trim();}}for(const el of main.querySelectorAll('.builder-leg-field')){const leg=(d.legs||[]).find(x=>x.id===el.dataset.key);if(!leg)continue;const k=el.dataset.field;if(k)leg[k]=k==='dutCount'?Math.max(1,Number(el.value)||1):el.value;}ensureBuilderSerials(d);normalizeBuilderTopology(d);return d}
function syncBuilderDesign({create=true,status=null}={}){if(!state?.settings?.builderDraft)return null;ensureValidationDesignStore();const d=state.settings.builderDraft;normalizeBuilderTopology(d);let id=state.settings.currentValidationDesignId||d.designId||'',rec=id?state.validationDesigns.find(x=>x.id===id):null;if(!rec&&create){id=nextValidationDesignId();d.designId=id;state.settings.currentValidationDesignId=id;rec={id,createdAt:new Date().toISOString(),status:'Draft',linkedProgrammeId:'',previousProgrammeIds:[]};state.validationDesigns.push(rec);}if(!rec)return null;d.designId=id;rec.project=d.project||'Untitled validation';rec.customer=d.customer||'';rec.product=d.product||'';rec.revision=d.revision||'';rec.dueDate=d.dueDate||'';rec.testCount=(d.legs||[]).length;rec.mainLegCount=new Set((d.legs||[]).map(builderMainLegNo)).size;rec.updatedAt=new Date().toISOString();if(status)rec.status=status;rec.draft=cloneData(d);rec.fingerprint=builderDesignFingerprint(d);return rec}
async function saveBuilderDesign(showToast=true){captureBuilderInputs();const rec=syncBuilderDesign({create:true,status:'Draft'});await saveState(state);if(showToast)toast(`${rec.id} saved. The validation design remains available until you explicitly reset/delete it.`);render();return rec}
