async function setBuilderStep(step){captureBuilderInputs();const d=getBuilderDraft();step=Math.max(1,Math.min(4,Number(step)||1));if(step>=2&&!d.project?.trim())return toast('Complete the programme details first.');if(step>=3&&!d.legs.length)return toast('Add at least one test before reviewing readiness.');d.builderStep=step;syncBuilderDesign({create:true,status:'Draft'});await saveState(state);render();window.scrollTo({top:0,behavior:'smooth'})}
function builderStepBar(step){const labels=['Programme & samples','Design test flow','Review readiness','Schedule'];return `<div class="designer-steps v115-steps">${labels.map((label,i)=>{const n=i+1,done=n<step,active=n===step;return`<button type="button" data-act="builder-step" data-id="${n}" class="${done?'done ':''}${active?'active':''}"><b>${done?'✓':n}</b><span>${label}</span></button>`}).join('')}</div>`}

