function builderLegLabel(cfg){const n=Math.max(1,Number(cfg.mainLegNo)||Number(cfg.stageNo)||1),branch=builderBranchPath(cfg),step=Math.max(1,Number(cfg.stepNo)||1);return branch?`${n}${branch}.${step}`:`${n}.${step}`;}
