 const specTest=`<div class="spec-entry-card"><div><strong>Define the required test specification</strong><span>Enter required conditions, measurement/accuracy, acceptance criteria, equipment/skill needs and expected duration. LabOS compares the requirement with the released Test Library.</span></div><div class="spec-entry-outcomes"><span>Standard fit → <b>0d development</b></span><span>Adaptation → <b>estimated development</b></span><span>No adequate method → <b>new-test development</b></span></div><button class="btn primary" data-act="builder-define-test">Define specs & assess</button></div>`;
 const summary=`<div class="builder-summary-strip card"><div><span>Main test legs</span><strong>${legCount}</strong></div><div><span>Tests in plan</span><strong>${S.items.length}</strong></div><div><span>Development needed</span><strong>${S.newCount}</strong></div><div><span>Master DUTs</span><strong>${S.totalDuts}</strong></div><div><span>Forecast cost</span><strong>${currency(state,S.cost,true)}</strong></div><div><span>Longest development</span><strong>${S.devDays}d</strong></div></div>`;
 let body='';
 if(step===1)body=`<div class="v115-step-intro"><strong>Step 1 · Define the programme and its physical samples</strong><span>This is the source of truth for customer/product identity, timing, sample availability and serialized DUT traceability.</span></div>${programmeSetup}<div class="grid section-grid equal builder-support" style="margin-top:14px">${sampleSetup}${serialSetup}</div>${templateSetup}<div class="builder-release card"><div><strong>Programme & samples captured</strong><span>Continue to construct or refine the executable validation flow.</span></div><div class="actions"><button class="btn" data-act="builder-create-draft">✓ Save now</button><button class="btn primary" data-act="builder-step" data-id="2">Continue to test flow →</button></div></div>${section('Saved validation designs',renderSavedValidationDesigns(),'Every step is auto-saved and can be reopened.')}`;
 else if(step===2)body=`<div class="v115-step-intro"><strong>Step 2 · Build the executable test flow</strong><span>Main Test Legs are independent. Within a leg, tests sequence, split recursively into parallel DUT paths, and merge under explicit topology control.</span></div>${builderGraph()}${summary}<div class="grid section-grid equal" style="margin-top:14px">${templateSetup}${section('Define required specs & assess development',specTest,'Use this when the test requirement is known but the method is not.')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Standard Test Library',`<div class="method-quick-list">${portfolioRows}</div>`,'Use released methods directly in the flow.')}${section('Lessons learned for selected tests',lessonsHtml,'Historical evidence follows the selected methods.')}</div><div class="builder-release card"><div><strong>Flow constructed?</strong><span>Next, LabOS checks samples, serial traceability, topology, dates and development readiness before it allows scheduling.</span></div><div class="actions"><button class="btn" data-act="builder-step" data-id="1">← Programme & samples</button><button class="btn primary" data-act="builder-step" data-id="3" ${!S.items.length?'disabled':''}>Review readiness →</button></div></div>`;
 else if(step===3)body=`<div class="v115-step-intro"><strong>Step 3 · Review readiness before scheduling</strong><span>Planning is requested only after the validation definition is coherent. Future sample availability is a schedulable constraint—not an automatic blocker.</span></div><div class="card readiness-panel"><div class="section-title"><div><strong>${R.ready?'Ready to request planning':'Resolve the highlighted readiness inputs'}</strong><small>${R.ready?'LabOS can construct a feasible schedule from the current validation definition.':'Planning stays locked until the blocking items below are resolved.'}</small></div>${pill(R.ready?'Ready':'Needs attention')}</div><div class="readiness-check-list">${R.checks.map(c=>`<div class="readiness-check ${c.ok?'ok':'bad'}"><b>${c.ok?'✓':'!'}</b><div><strong>${esc(c.label)}</strong><small>${esc(c.detail)}</small></div>${!c.ok&&c.id==='programme'?`<button class="btn small" data-act="builder-step" data-id="1">Fix</button>`:!c.ok&&['sample','serials','dates'].includes(c.id)?`<button class="btn small" data-act="builder-step" data-id="1">Fix</button>`:!c.ok&&c.id==='flow'?`<button class="btn small" data-act="builder-step" data-id="2">Fix</button>`:''}</div>`).join('')}</div></div>${summary}<div class="card v115-planning-preview"><div><strong>Sample planning gate</strong><span>${esc(R.checks.find(x=>x.id==='sample')?.detail||'')}</span></div><div><strong>Serialized population</strong><span>${d.serialNumbers.length} DUT identities will be created exactly as shown in Step 1.</span></div><div><strong>Planning mode</strong><span>${esc(d.planningMode||'Assisted')} · protected programme planning remains the default.</span></div></div><div class="builder-release card"><div><strong>${R.ready?'Ready for scheduling':'Planning request locked'}</strong><span>${R.ready?'Requesting planning creates the programme, sample/DUT records, any linked prototype dependency and the coordinated validation schedule.':'Use the Fix actions above; accepting a warning is not enough.'}</span></div><div class="actions"><button class="btn" data-act="builder-step" data-id="2">← Edit test flow</button><button class="btn primary" data-act="builder-create-plan" ${R.ready?'':'disabled'}>Request planning →</button></div></div>`;
 else{const design=state.validationDesigns.find(x=>x.id===d.designId),pid=design?.linkedProgrammeId,p=state.programmes.find(x=>x.id===pid);body=`<div class="v115-step-intro"><strong>Step 4 · Scheduled validation</strong><span>The validation definition remains editable and traceable to the generated operational programme.</span></div>${p?`<div class="card v115-schedule-result"><div class="section-title"><div><strong>${p.id} · ${esc(p.project)}</strong><small>Forecast ${fmtDate(p.forecastCompletion)} · required ${fmtDate(p.dueDate)} · ${esc(p.scheduleRisk||p.status||'')}</small></div>${pill(p.scheduleRisk||p.status||'Planned')}</div><div class="actions"><button class="btn primary" data-act="open-project-plan" data-id="${p.id}">Open planning</button><button class="btn" data-act="builder-step" data-id="2">Edit validation flow</button><button class="btn" data-act="builder-step" data-id="1">Edit samples / serials</button></div></div>`:`<div class="callout warning"><strong>No operational schedule has been generated yet.</strong><div>Return to readiness and request planning.</div><button class="btn primary" data-act="builder-step" data-id="3">Review readiness</button></div>`}${section('Saved validation designs',renderSavedValidationDesigns(),'Design revisions and linked planning remain traceable.')}`;}
 return pageHead('Validation Plan Designer',step===1?'Define programme scope, sample readiness and DUT traceability before designing tests.':step===2?'Construct the validation architecture visually with recursive branches and explicit sequence/merge logic.':step===3?'Check that the design is truly ready to become an operational schedule.':'Open or revise the schedule generated from this validation design.',`<button class="btn" data-act="builder-new-design">＋ New validation</button><button class="btn" data-act="builder-create-draft">✓ Save now</button>`)
