function forecastDemandViz(cf,metric='equipment'){
 const rows=cf.weeks.slice(0,Math.min(16,cf.weeks.length));if(!rows.length)return'<div class="empty">No forecast demand.</div>';
 const vals=rows.map(r=>metric==='staff'?[r.confirmedStaff,r.pipelineStaff]:[r.confirmedEq,r.pipelineEq]),max=Math.max(1,...vals.map(v=>v[0]+v[1]));
 return `<div class="forecast-legend"><span><i class="legend-dot teal"></i>Confirmed / ongoing</span><span><i class="legend-dot blue"></i>${cf.mode==='full'?'Full pipeline':'Probability-weighted pipeline'}</span></div><div class="future-bars">${rows.map((r,i)=>{const v=vals[i],tot=v[0]+v[1],gap=metric==='staff'?r.staffGapHours:r.equipmentGapHours;return`<div class="future-col" title="Week ${i+1}: ${Math.round(tot)}h demand${gap?` · ${gap}h unmet`:''}"><div class="future-value">${Math.round(tot)}h</div><div class="future-stack"><i class="confirmed" style="height:${v[0]/max*100}%"></i><i class="pipeline" style="height:${v[1]/max*100}%"></i></div><div class="future-gap ${gap?'risk':''}">${gap?`${gap}h gap`:'capacity OK'}</div><span>${r.label}</span></div>`}).join('')}</div>`;
}
function readinessGauge(value,label='readiness'){return `<div class="readiness-gauge" style="--g:${Math.max(0,Math.min(100,value))}"><div><strong>${value}%</strong><span>${esc(label)}</span></div></div>`}
function gapTable(rows,type){const top=rows.filter(x=>x.gapHours>0||x.peakUtil>=75).slice(0,12);if(!top.length)return'<div class="empty">No forecast constraint in the selected horizon.</div>';return `<div class="table-wrap"><table><thead><tr><th>${type==='equipment'?'Equipment type':'Skill'}</th><th>Confirmed h</th><th>Pipeline h</th><th>Capacity h</th><th>Peak util.</th><th>Gap</th><th>Need</th></tr></thead><tbody>${top.map(x=>`<tr><td><strong>${esc(type==='equipment'?x.type:x.skill)}</strong></td><td>${Math.round(x.confirmed)}</td><td>${Math.round(x.pipeline)}</td><td>${Math.round(x.capacity)}</td><td>${pill(`${x.peakUtil}%`)}</td><td>${Math.round(x.gapHours)}h</td><td><strong>${type==='equipment'?`${x.unitsGap} asset(s)`:`${x.fteGap} FTE`}</strong></td></tr>`).join('')}</tbody></table></div>`}
function auditStatusViz(a){const groups={};for(const i of a.items){groups[i.section]=groups[i.section]||{name:i.section,total:0,ok:0,risk:0};groups[i.section].total++;if(i.status==='Conform')groups[i.section].ok++;if(['Major','Minor','OFI'].includes(i.status))groups[i.section].risk++;}return horizontalViz(Object.values(groups).map(g=>({name:g.name,count:Math.round(g.ok/Math.max(1,g.total)*100),delayHours:g.risk})),'count','%')}
function opportunityEstimateRow(o){const e=inferOpportunityPlan(state,o);return `<tr><td><strong>${o.id} · ${esc(o.name)}</strong><div class="small muted">${esc(o.customer)} · ${esc(o.product)}</div></td><td>${pill(`${o.probability}%`)}</td><td>${fmtDate(o.expectedStart)}</td><td>${e.source}<div class="small muted">${e.similarProgrammeId||'—'} · similarity ${e.similarity}%</div></td><td>${e.methods.length} methods</td><td>${Math.round(e.equipmentHours)}h</td><td>${Math.round(e.staffHours)}h</td><td><button class="btn small" data-act="edit-opportunity" data-id="${o.id}">Edit</button> <button class="btn small" data-act="convert-opportunity" data-id="${o.id}">Build</button></td></tr>`}

function renderCapacity(){const weeks=Number(state.settings.capacityHorizon)||12,mode=state.settings.pipelineMode||'weighted',cf=capacityForecast(state,weeks,mode),peakEq=Math.max(0,...cf.weeks.map(x=>x.equipmentUnitsGap)),peakFte=Math.max(0,...cf.weeks.map(x=>x.staffFteGap)),hiProb=state.opportunities.filter(o=>o.probability>=60&&o.status!=='Lost').length;return pageHead('Demand, Staffing & Equipment Forecast','Forward-looking resource plan combining committed laboratory work with probability-weighted potential projects',`<button class="btn" data-act="export-capacity-csv">⇩ Forecast CSV</button><button class="btn primary" data-act="add-opportunity">＋ Potential Project</button>`)+`<div class="period-bar card"><div class="period-title"><strong>Forecast model</strong><span>Ongoing projects + potential-project demand inferred from expected validation plans or the most similar existing programme</span></div><label>Horizon<select id="capacityHorizon">${[4,8,12,26].map(x=>`<option value="${x}" ${weeks===x?'selected':''}>${x} weeks</option>`).join('')}</select></label><label>Pipeline<select id="pipelineMode"><option value="committed" ${mode==='committed'?'selected':''}>Committed only</option><option value="weighted" ${mode==='weighted'?'selected':''}>Probability weighted</option><option value="full" ${mode==='full'?'selected':''}>Full pipeline / if all won</option></select></label></div>`+
 `<div class="grid kpi visual-kpis">${kpiCard('Potential projects',state.opportunities.filter(o=>o.status!=='Lost').length,`${hiProb} at ≥60% probability`)}${kpiCard('Weighted pipeline',`${cf.weightedPipeline.toFixed(1)} projects`,'Probability-equivalent demand')}${kpiCard('Equipment gap weeks',cf.equipmentGapWeeks,`${weeks}-week horizon`)}${kpiCard('Staff gap weeks',cf.staffGapWeeks,`${weeks}-week horizon`)}${kpiCard('Peak equipment need',`${peakEq} asset(s)`,'Beyond current effective capacity')}${kpiCard('Peak staffing need',`${peakFte} FTE`,'Qualified skill capacity gap')}</div>`+
 `<div class="grid section-grid equal">${section('Future equipment demand',forecastDemandViz(cf,'equipment'),'Confirmed bookings plus selected pipeline scenario')}${section('Future qualified-staff demand',forecastDemandViz(cf,'staff'),'Attended hours by required competency')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Equipment types to add / protect',gapTable(cf.equipment,'equipment'),'Ranked by forecast gap and peak utilisation')}${section('Skills / staffing to build',gapTable(cf.staff,'staff'),'FTE gap uses 80% sustainable workload capacity')}</div>`+
 `<div style="margin-top:14px">${section('Potential-project pipeline & similarity estimate',`<div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Probability</th><th>Expected start</th><th>Forecast basis</th><th>Validation plan</th><th>Equipment</th><th>Staff</th><th>Action</th></tr></thead><tbody>${state.opportunities.slice().sort((a,b)=>b.probability-a.probability).map(opportunityEstimateRow).join('')}</tbody></table></div>`,'If a validation plan is not supplied, LabOS estimates demand from the selected/most similar existing programme')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Management interpretation',`<div class="decision-list">${cf.equipment.filter(x=>x.gapHours>0).slice(0,5).map(x=>`<div><span class="decision-icon">⚙</span><div><strong>${esc(x.type)}</strong><p>Peak utilisation ${x.peakUtil}% with ${Math.round(x.gapHours)}h unmet demand. Plan ${x.unitsGap} additional/contingency asset(s), outsource, or rephase demand.</p></div></div>`).join('')||'<div class="empty">No equipment addition indicated.</div>'}${cf.staff.filter(x=>x.gapHours>0).slice(0,5).map(x=>`<div><span class="decision-icon">♙</span><div><strong>${esc(x.skill)}</strong><p>Peak utilisation ${x.peakUtil}% with a ${x.fteGap} FTE gap. Cross-train, hire/contract, or move demand.</p></div></div>`).join('')}</div>`,'Decision support rather than simple utilisation reporting')}${section('Forecast assumptions',`<div class="callout"><strong>Committed work:</strong> current resource-constrained bookings.<br><strong>Pipeline:</strong> ${mode==='weighted'?'probability-weighted':'scenario-selected'} method demand spread across expected programme duration.<br><strong>Equipment capacity:</strong> 75% of calendar capacity less planned downtime.<br><strong>Staff capacity:</strong> 80% of qualified working-time capacity.<br><strong>Similarity:</strong> expected methods when provided; otherwise the selected/closest existing programme profile.</div>`,'All assumptions are deterministic and visible')}</div>`;}

function renderMaintenance(){const ms=maintenanceSummary(state,90),rows=ms.policies.slice().sort((a,b)=>a.days-b.days),last=state.settings.lastMaintenanceOptimization,syn=serviceSynergy(state,120),health=predictiveAssetSummary(state);return pageHead('Equipment Service, Maintenance & Calibration Plan','Maintenance and calibration share one asset-service strategy so downtime is bundled where practical and protected against laboratory demand',`<button class="btn" data-act="export-maintenance-csv">⇩ Maintenance CSV</button><button class="btn" data-act="add-maintenance">＋ Downtime Event</button><button class="btn primary" data-act="optimize-maintenance">⚙ Optimize Service Windows & Replan</button>`)+`<div class="grid kpi visual-kpis">${kpiCard('Due next 90 days',ms.due.length,`${ms.overdue.length} overdue`)}${kpiCard('Predictive high-risk assets',health.high,`${health.avgHealth}% average asset health`)}${kpiCard('Combined opportunities',syn.filter(x=>x.combine).length,'Maintenance + calibration within 21d')}${kpiCard('Avoidable downtime',`${syn.reduce((a,x)=>a+x.avoidedDowntimeHours,0)}h`,'Estimated duplicate service downtime')}${kpiCard('Planned PM windows',ms.planned.length,`${ms.plannedHours}h planned downtime`)}${kpiCard('Plan status',state.settings.planDirty?'Refresh required':'Integrated','All service blocks constrain scheduler')}</div><div class="grid section-grid equal">${section('Maintenance / calibration synergy',`<div class="maintenance-roadmap">${syn.slice(0,12).map(x=>`<div class="maint-road ${x.combine?'urgent':''}"><div><strong>${x.equipmentId} · ${esc(x.name)}</strong><small>maintenance ${fmtDate(x.maintenanceDue)} · calibration ${fmtDate(x.calibrationDue)}</small></div><div><span>${x.combine?`bundle · save ~${x.avoidedDowntimeHours}h`:`${Math.abs(x.deltaDays??0)}d separation`}</span>${pill(x.combine?'Combine':'Separate')}</div></div>`).join('')}</div>`,'Optimizer prefers service windows near calibration when due dates are compatible')}${section('Optimised downtime windows',`<div class="list">${state.maintenance.filter(m=>m.type==='Preventive Maintenance').sort((a,b)=>new Date(a.start)-new Date(b.start)).map(m=>`<div class="list-row"><div><strong>${m.equipmentId} · ${esc(m.reason)}</strong><small>${fmtDate(m.start,true)} → ${fmtDate(m.end,true)} · ${m.calibrationAligned?'calibration-aligned · ':''}${m.optimized?'demand-optimised':'manual'}</small></div>${pill(m.status||'Planned')}</div>`).join('')||'<div class="empty">Run optimisation to place service downtime.</div>'}</div>`,'One asset availability calendar is consumed by automatic planning')}</div><div style="margin-top:14px">${section('Equipment maintenance policy & readiness',`<div class="table-wrap"><table><thead><tr><th>Asset</th><th>Criticality</th><th>Strategy</th><th>Condition</th><th>Failure risk</th><th>Predictive health</th><th>Next due</th><th>Duration</th><th>Planned window</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="link mono" data-entity="equipment" data-id="${x.equipmentId}">${x.equipmentId}</span><div class="small muted">${esc(x.equipment?.name||'')}</div></td><td>${pill(x.criticality)}</td><td>${esc(x.strategy)}</td><td><div class="progress"><span style="width:${x.conditionScore}%"></span></div>${x.conditionScore}/100</td><td>${pill(x.failureRisk)}</td><td>${(()=>{const h=health.rows.find(z=>z.eq.id===x.equipmentId);return h?`${h.health}/100 · ${pill(h.band)}<div class="small muted">failure window ~${h.predictedFailureWindowDays}d</div>`:'—'})()}</td><td>${fmtDate(x.nextDueDate)}</td><td>${x.durationHours}h</td><td>${x.event?`${fmtDate(x.event.start,true)}<div class="small muted">${x.event.calibrationAligned?'combined service':''}</div>`:'—'}</td><td><button class="btn small" data-act="edit-maint-policy" data-id="${x.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`,'Condition, calibration and demand are evaluated together')}</div>`;}
function renderAudit(){const std=state.settings.auditStandard||'ISO17025',audits=state.audits.filter(a=>a.standard===std),a=audits.find(x=>x.id===state.settings.auditRecord)||audits.at(-1);if(a)state.settings.auditRecord=a.id;const M=auditScore(a),S=AUDIT_STANDARDS[std],findings=a.items.filter(i=>['Major','Minor','OFI'].includes(i.status));return pageHead('Audit & Compliance','Run an internal laboratory-readiness audit against ISO/IEC 17025 or IATF 16949 themes, capture evidence/findings and track actions',`<button class="btn" data-act="export-audit-csv" data-id="${a.id}">⇩ Audit CSV</button><button class="btn" data-act="new-audit">＋ New Audit</button><button class="btn primary" data-act="audit-auto" data-id="${a.id}">▶ Assess Current System Evidence</button>`)+`<div class="period-bar card"><div class="period-title"><strong>Audit basis</strong><span>${esc(S.note)}</span></div><label>Standard<select id="auditStandard"><option value="ISO17025" ${std==='ISO17025'?'selected':''}>ISO/IEC 17025:2017</option><option value="IATF16949" ${std==='IATF16949'?'selected':''}>IATF 16949:2016</option></select></label><label>Audit<select id="auditRecord">${audits.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${x.id} · ${esc(x.name)}</option>`).join('')}</select></label></div>`+
 `<div class="audit-banner card"><div>${readinessGauge(M.score,`${S.name} readiness`)}</div><div class="audit-banner-copy"><h2>${a.id} · ${esc(a.name)}</h2><p>${esc(a.scope)} · Auditor ${esc(a.auditor)} · planned ${fmtDate(a.plannedDate)}</p><div class="actions">${pill(a.status)} ${pill(`${M.completion}% assessed`)}</div><small>Prototype internal-audit support only. It does not certify conformity, replace competent auditors, licensed standards, accreditation/certification rules or customer-specific requirements.</small></div></div>`+
 `<div class="grid kpi compact-kpis">${kpiCard('Readiness score',`${M.score}%`,`${M.audited}/${M.total} items assessed`)}${kpiCard('Major findings',M.major,'Immediate systemic attention')}${kpiCard('Minor findings',M.minor,'Corrective action required')}${kpiCard('Opportunities',M.ofi,'Improvement / resilience')}${kpiCard('Open NC actions',M.open,'Major + minor')}${kpiCard('Audit completion',`${M.completion}%`,a.status)}</div>`+
 `<div class="grid section-grid equal">${section('Conformity by process area',auditStatusViz(a),'Based on current audit item status')}${section('Priority findings',`<div class="list">${findings.sort((x,y)=>(({Major:3,Minor:2,OFI:1}[y.status]||0)-({Major:3,Minor:2,OFI:1}[x.status]||0))).slice(0,8).map(i=>`<div class="list-row"><div><strong>${i.reference} · ${esc(i.title)}</strong><small>${esc(i.finding||i.evidence)}</small></div>${pill(i.status)}</div>`).join('')||'<div class="empty">No findings.</div>'}</div>`,'System evidence creates initial readiness signals; auditor judgement remains authoritative')}</div>`+
 `<div style="margin-top:14px">${section(`${S.name} audit workbench`,`<div class="table-wrap"><table><thead><tr><th>Ref.</th><th>Process / expectation</th><th>Status</th><th>System evidence</th><th>Finding / action need</th><th>Owner / due</th><th>Audit</th></tr></thead><tbody>${a.items.map(i=>`<tr><td><strong>${esc(i.reference)}</strong><div class="small muted">${esc(i.section)}</div></td><td><strong>${esc(i.title)}</strong><div class="small muted">${esc(i.expectation)}</div></td><td>${pill(i.status)}</td><td>${esc(i.evidence||'Not assessed')}</td><td>${esc(i.finding||'—')}</td><td>${esc(i.owner||'—')}<div class="small muted">${fmtDate(i.dueDate)}</div></td><td><button class="btn small" data-act="audit-item" data-audit="${a.id}" data-item="${i.id}">Assess</button></td></tr>`).join('')}</tbody></table></div>`,'Clause-theme summaries are original workflow prompts; consult the licensed standard for authoritative requirements')}</div>`+
 `<div class="callout ${std==='IATF16949'?'warning':''}" style="margin-top:14px"><strong>Standards status in this prototype:</strong> ${std==='ISO17025'?'ISO/IEC 17025:2017 is the current confirmed edition used for this readiness workbench.':'IATF 16949:2016 is used for the current workbench. IATF has announced active work on a second edition; future releases should update this checklist when the new edition becomes effective.'}</div>`;}

function addOpportunityModal(id=null){const o=id?state.opportunities.find(x=>x.id===id):null;openModal(`<h2>${o?'Edit':'Add'} Potential Project</h2><p class="small muted">Potential projects are excluded from committed planning but included in capacity forecasts according to probability/scenario.</p><div class="modal-grid"><div class="field"><label>Name</label><input id="opName" value="${esc(o?.name||'New validation opportunity')}"></div><div class="field"><label>Customer</label><input id="opCustomer" value="${esc(o?.customer||'Prospective Customer')}"></div><div class="field"><label>Product</label><input id="opProduct" value="${esc(o?.product||'New product')}"></div><div class="field"><label>Probability %</label><input id="opProb" type="number" min="0" max="100" value="${o?.probability??50}"></div><div class="field"><label>Expected start</label><input id="opStart" type="date" value="${new Date(o?.expectedStart||dayISO(45)).toISOString().slice(0,10)}"></div><div class="field"><label>Expected completion</label><input id="opDue" type="date" value="${new Date(o?.dueDate||dayISO(150)).toISOString().slice(0,10)}"></div><div class="field"><label>Pipeline status</label><select id="opStatus">${['Early','Proposal','Qualified','Negotiation','Won','Lost'].map(x=>`<option ${o?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Most similar existing programme</label><select id="opSimilar"><option value="">Auto infer</option>${state.programmes.map(p=>`<option value="${p.id}" ${o?.similarProgrammeId===p.id?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select></div></div><div class="field"><label>Expected validation plan (optional; Ctrl/Cmd-click multiple)</label><select id="opMethods" multiple size="10">${state.methods.filter(m=>m.active).map(m=>`<option value="${m.id}" ${(o?.expectedMethodIds||[]).includes(m.id)?'selected':''}>${m.id} · ${esc(m.name)} · ${m.category}</option>`).join('')}</select></div><div class="field"><label>Notes / assumptions</label><textarea id="opNotes">${esc(o?.notes||'')}</textarea></div><div class="actions"><button id="saveOpp" class="btn primary">Save & Recalculate Forecast</button></div>`);document.getElementById('saveOpp').onclick=async()=>{const start=document.getElementById('opStart').value,due=document.getElementById('opDue').value,prob=Math.max(0,Math.min(100,Number(document.getElementById('opProb').value)||0));if(!start||!due||new Date(due)<=new Date(start))return toast('Expected completion must be after expected start.');const obj=o||{id:`OPP-${String(state.opportunities.length+1).padStart(3,'0')}`};Object.assign(obj,{name:document.getElementById('opName').value.trim()||'Potential project',customer:document.getElementById('opCustomer').value.trim(),product:document.getElementById('opProduct').value.trim(),probability:prob,expectedStart:new Date(start+'T08:00:00Z').toISOString(),dueDate:new Date(due+'T17:00:00Z').toISOString(),status:document.getElementById('opStatus').value,similarProgrammeId:document.getElementById('opSimilar').value||null,expectedMethodIds:[...document.getElementById('opMethods').selectedOptions].map(x=>x.value),profileCategories:[],notes:document.getElementById('opNotes').value});if(!o)state.opportunities.push(obj);state.audit.push(audit(o?'Potential project changed':'Potential project added',obj.id,'',`${obj.probability}% · ${obj.status}`));await persist();closeModal();render();toast(`${obj.id} saved; future capacity forecast recalculated.`)}}
async function convertOpportunity(id){const o=state.opportunities.find(x=>x.id===id);if(!o)return;const est=inferOpportunityPlan(state,o),d=defaultBuilderDraft();d.project=o.name;d.customer=o.customer;d.product=o.product;d.priority=o.probability>=75?'High':'Normal';d.businessPriority=Math.max(1,Math.min(100,Math.round(o.probability)));d.dueDate=new Date(o.dueDate).toISOString().slice(0,10);d.dutCount=Number(o.dutCount||10);d.budget=Number(o.budget||0);d.selected={};for(const mid of est.methodIds)d.selected[mid]={staffPolicy:'Auto',staffId:''};d.customMethods=[];d.notes=`Pipeline conversion from ${o.id} · ${est.source}${est.similarProgrammeId?` · similar to ${est.similarProgrammeId} (${est.similarity}%)`:''}`;state.settings.builderDraft=d;state.audit.push(audit('Opportunity sent to Programme Builder',o.id,'',`${est.methodIds.length} inferred methods`));await persist();go('builder');toast(`${o.id} loaded into Programme Builder from ${est.source}.`)}
function editMaintenancePolicyModal(id){const p=state.maintenancePolicies.find(x=>x.id===id),eq=state.equipment.find(e=>e.id===p?.equipmentId);if(!p)return;openModal(`<h2>${p.equipmentId} · Maintenance Policy</h2><div class="callout"><strong>${esc(eq?.name)}</strong> · ${esc(eq?.type)}</div><div class="modal-grid"><div class="field"><label>Criticality</label><select id="mpCrit">${['Critical','High','Medium','Low'].map(x=>`<option ${p.criticality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Strategy</label><select id="mpStrategy">${['Time based','Condition + time based','Usage based'].map(x=>`<option ${p.strategy===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Interval days</label><input id="mpInterval" type="number" min="7" value="${p.intervalDays}"></div><div class="field"><label>Planned duration hours</label><input id="mpDuration" type="number" min="1" value="${p.durationHours}"></div><div class="field"><label>Next due date</label><input id="mpDue" type="date" value="${new Date(p.nextDueDate).toISOString().slice(0,10)}"></div><div class="field"><label>Condition score 0–100</label><input id="mpCondition" type="number" min="0" max="100" value="${p.conditionScore}"></div><div class="field"><label>Failure risk</label><select id="mpRisk">${['Low','Medium','High'].map(x=>`<option ${p.failureRisk===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label><input id="mpLock" type="checkbox" ${p.locked?'checked':''}> Freeze maintenance window when optimised</label></div></div><button id="saveMP" class="btn primary">Save Policy</button>`);document.getElementById('saveMP').onclick=async()=>{Object.assign(p,{criticality:document.getElementById('mpCrit').value,strategy:document.getElementById('mpStrategy').value,intervalDays:Math.max(7,Number(document.getElementById('mpInterval').value)||90),durationHours:Math.max(1,Number(document.getElementById('mpDuration').value)||8),nextDueDate:new Date(document.getElementById('mpDue').value+'T17:00:00Z').toISOString(),conditionScore:Math.max(0,Math.min(100,Number(document.getElementById('mpCondition').value)||0)),failureRisk:document.getElementById('mpRisk').value,locked:document.getElementById('mpLock').checked});state.audit.push(audit('Maintenance policy changed',p.id,'',`${p.nextDueDate} · ${p.durationHours}h`));await persist();closeModal();render();toast(`${p.equipmentId} maintenance policy saved.`)}}
function addMaintenanceModal(){openModal(`<h2>Add Planned Downtime</h2><div class="modal-grid"><div class="field"><label>Equipment</label><select id="meq">${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Type</label><select id="mtype"><option>Preventive Maintenance</option><option>Maintenance</option><option>Calibration</option><option>Reserved</option></select></div><div class="field"><label>Start</label><input id="mstart" type="datetime-local" value="${dayISO(14,8).slice(0,16)}"></div><div class="field"><label>Duration hours</label><input id="mdur" type="number" min="1" value="8"></div></div><div class="field"><label>Reason</label><textarea id="mreason">Planned preventive maintenance</textarea></div><button id="saveME" class="btn primary">Save Downtime & Replan</button>`);document.getElementById('saveME').onclick=async()=>{const start=new Date(document.getElementById('mstart').value+'Z'),dur=Math.max(1,Number(document.getElementById('mdur').value)||8),end=new Date(start.getTime()+dur*3600000),eq=document.getElementById('meq').value;if(state.bookings.some(b=>b.equipmentId===eq&&b.locked&&timeOverlap(start,end,b.start,b.end)))return toast('Rejected: downtime overlaps a locked equipment booking.');state.maintenance.push({id:`MNT-${String(state.maintenance.length+1).padStart(3,'0')}`,equipmentId:eq,start:start.toISOString(),end:end.toISOString(),type:document.getElementById('mtype').value,reason:document.getElementById('mreason').value.trim(),status:'Planned',optimized:false});const r=scheduleAll(state);state=r.data;lastPlanDiagnostics=r.diagnostics;state.audit.push(audit('Planned downtime added',eq,'',`${start.toISOString()} · ${dur}h`));await persist();closeModal();render();toast(`Downtime saved; ${r.diagnostics.moved.length} bookings moved.`)}}
