function developmentEstimateForNewTest(category,equipmentType,skill){
 const completed=(state.devTasks||[]).filter(d=>d.completeDate||d.status==='Review').map(d=>{const leg=state.legs.find(l=>l.id===d.legId),m=leg&&state.methods.find(x=>x.id===leg.methodId);return{d,m}});
 const similar=completed.filter(x=>(x.m?.category===category)||(x.m?.equipmentType===equipmentType)||(x.d.requiredSkills||[]).includes(skill));
 const pool=similar.length?similar:completed;
 const avg=(key,fallback)=>pool.length?Math.round(pool.reduce((a,x)=>a+Number(x.d[key]??fallback),0)/pool.length*10)/10:fallback;
 const elapsed=avg('actualElapsedDays',avg('elapsedDays',7)),eng=avg('actualEngineeringHours',avg('estimatedEngineeringHours',40)),tech=avg('actualTechnicianHours',avg('estimatedTechnicianHours',16));
 return{days:Math.max(3,Math.round(elapsed)),engineeringHours:Math.max(12,Math.round(eng)),technicianHours:Math.max(4,Math.round(tech)),similarCount:similar.length,confidence:Math.min(95,35+similar.length*15),basis:similar.length?`${similar.length} similar completed development task(s)`:'portfolio development baseline'};
}
