function prototypeScopeType(r){return r?.linkedScopeType||((r?.linkedTestLegId||r?.linkedMainLegNo)?(r.linkedTestLegId?'test':'leg'):(r?.linkedProgrammeId?'programme':'standalone'))}
function prototypeTargetLegs(r){if(!r?.linkedProgrammeId)return[];const all=state.legs.filter(l=>l.programmeId===r.linkedProgrammeId);if(prototypeScopeType(r)==='test'&&r.linkedTestLegId)return all.filter(l=>l.id===r.linkedTestLegId);if(prototypeScopeType(r)==='leg'&&Number(r.linkedMainLegNo))return all.filter(l=>Math.max(1,Number(l.validationLegNo)||Number(l.sequence)||1)===Number(r.linkedMainLegNo));return all.filter(l=>!(l.predecessorIds||[]).length).length?all.filter(l=>!(l.predecessorIds||[]).length):all}
function prototypeTargetLabel(r){const p=state.programmes.find(x=>x.id===r?.linkedProgrammeId);if(!p)return'Standalone';if(prototypeScopeType(r)==='test'){const l=state.legs.find(x=>x.id===r.linkedTestLegId);return`${p.id} → ${l?`${reportTestLabel(l)} · ${l.name}`:'specific test'}`}if(prototypeScopeType(r)==='leg')return`${p.id} → Test Leg ${r.linkedMainLegNo}`;return`${p.id} → programme sample gate`}
