async function coordinatePrototypeValidation(r,{reason='Prototype update',show=true}={}){if(!r)return null;const pid=r.linkedProgrammeId,restore=planningRestorePoint(`${reason} · ${r.id}`);const out=schedulePrototypeBuilds(state,{programmeId:pid||null});applyPrototypeDependency(r);let impact=[];if(pid){const base=cloneData(state),rr=scheduleProgramme(state,pid);const beforeForecast=base.programmes.find(x=>x.id===pid)?.forecastCompletion;state=rr.data;ensureStateShape(state);const afterForecast=state.programmes.find(x=>x.id===pid)?.forecastCompletion;lastPlanDiagnostics=rr.diagnostics;state.settings.planDirty=false;pushPlanningUndo(restore);impact=[{id:pid,beforeForecast,afterForecast,moved:rr.diagnostics?.moved?.length||0}]}state.audit.push(audit('Prototype / validation coordinated',r.id,'',`${prototypeTargetLabel(r)} · protected replan`));await persist();if(show)prototypeCoordinationModal(r.id,impact,out);return{impact,out}}
