function prototypePriorityModal(id){const r=state.prototypeRequests.find(x=>x.id===id),p=state.programmes.find(x=>x.id===r?.linkedProgrammeId);if(!r||!p)return;const others=state.programmes.filter(x=>x.id!==p.id);openModal(`<h2>${r.id} · Optional portfolio trade-off</h2><div class="callout warning"><strong>Protected replanning remains the default.</strong><div>Select only programmes that may yield capacity to ${p.id}. Unselected programmes stay protected.</div></div><div class="check-grid">${others.map(x=>`<label class="review-check"><input class="protoFlex" type="checkbox" value="${x.id}"><span><strong>${x.id} · ${esc(x.project)}</strong><small>${x.priority} · forecast ${fmtDate(x.forecastCompletion)} · due ${fmtDate(x.dueDate)}</small></span></label>`).join('')}</div><button id="previewProtoTrade" class="btn primary">Simulate & compare impact</button>`);document.getElementById('previewProtoTrade').onclick=()=>{const ids=[...modalBody.querySelectorAll('.protoFlex:checked')].map(x=>x.value);prototypePriorityReviewModal(id,ids)}}
function prototypePriorityReviewModal(id,flexIds){const r=state.prototypeRequests.find(x=>x.id===id),pid=r?.linkedProgrammeId;if(!r||!pid)return;const base=cloneData(state),allowed=[pid,...flexIds],rr=scheduleProgrammeSet(base,allowed),snap=capturePlanningSnapshot(state,'Before prototype priority trade-off'),diff=planningDiff(snap,rr.data),rows=replanProgrammeImpacts(state,rr.data,diff,pid);openModal(`<h2>${r.id} · Portfolio impact before approval</h2><div class="callout"><strong>What is allowed to move?</strong><div>${allowed.join(', ')}</div></div>${impactTable(rows,pid)}<div class="actions"><button id="acceptProtoTrade" class="btn primary">Accept this portfolio replan</button><button id="rejectProtoTrade" class="btn">Reject · keep protected plan</button></div>`);document.getElementById('acceptProtoTrade').onclick=async()=>{pushPlanningUndo(planningRestorePoint(`Before ${r.id} portfolio replan`));state=rr.data;ensureStateShape(state);state.audit.push(audit('Prototype priority portfolio replan accepted',r.id,'Protected',allowed.join(', ')));await persist();closeModal();render();toast('Portfolio replan accepted. Undo remains available.');};document.getElementById('rejectProtoTrade').onclick=()=>{closeModal();toast('Portfolio alternative rejected; protected plan retained.')}}
function prototypeLinkFields(r,pid=r.linkedProgrammeId||'',scope=prototypeScopeType(r)){return `<div class="modal-grid"><label>Validation programme<select id="peProg"><option value="">Standalone</option>${state.programmes.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select></label><label>Link level<select id="peScope"><option value="programme" ${scope==='programme'?'selected':''}>Entire programme sample gate</option><option value="leg" ${scope==='leg'?'selected':''}>Specific Test Leg</option><option value="test" ${scope==='test'?'selected':''}>Specific test</option></select></label><label id="peTargetWrap">Specific target<select id="peTarget"></select></label></div>`}
