function guidedCustodyDispositionModal(dutId,legId){const d=state.duts.find(x=>x.id===dutId),l=state.legs.find(x=>x.id===legId);if(!d||!l)return;const cs=custodyPlanningState(dutId);openModal(`<h2>${dutId} · Controlled disposition</h2><div class="callout"><strong>Authoritative custody: ${esc(cs.status)}</strong><div>Master DUT state: ${esc(d.status)}. This action must describe what physically happened to the sample. Selecting “Release” is not merely an acknowledgement.</div></div><label>Disposition<select id="gcdType"><option value="Released">Release for validation use</option><option value="Quarantined">Keep quarantined</option><option value="Disposed">Dispose / unusable</option></select></label><label>Evidence / reason<textarea id="gcdEvidence" placeholder="inspection record, deviation disposition, concession, scrap record, etc."></textarea></label><button id="saveGcd" class="btn primary">Record disposition & recheck plan</button>`);document.getElementById('saveGcd').onclick=async()=>{const type=document.getElementById('gcdType').value,note=document.getElementById('gcdEvidence').value.trim();if(!note)return toast('Disposition evidence/reason is required.');const loc=state.sampleLocations?.[0]?.id||'Sample Store';moveDut(state,dutId,loc,type,state.settings.actor,note);if(type==='Released')d.status='Available';else if(type==='Quarantined')d.status='Quarantined';else if(type==='Disposed')d.status='Disposed';const restore=planningRestorePoint(`Before custody resolution ${dutId}`),rr=scheduleProgramme(state,l.programmeId);state=rr.data;ensureStateShape(state);lastPlanDiagnostics=rr.diagnostics;pushPlanningUndo(restore);state.audit.push(audit('Guided DUT disposition',dutId,cs.status,`${type} · ${note}`));await persist();closeModal();guidedBlockerModal(legId)}}
