function renderPlanningV100(){const pid=state.settings.planningProject||'',p=state.programmes.find(x=>x.id===pid),mode=pid?(p?.planningMode||'Assisted'):(state.settings.portfolioPlanningMode||'Assisted'),base=renderPlanning();const expl=`<div class="planning-mode-banner card"><div><strong>${pid?`${p?.id} planning`:'Laboratory portfolio planning'} · ${mode} mode</strong><span>${mode==='Auto'?'LabOS may apply feasible schedule changes automatically; every booking can still be overridden and locked.':mode==='Assisted'?'LabOS calculates the best feasible schedule, shows what will move, and waits for approval before applying meaningful changes.':'LabOS recommends feasible options but does not change bookings unless you choose to apply one.'}</span></div><div class="actions">${pid?`<button class="btn" data-act="project-controls" data-id="${pid}">Planning controls</button>${(state.settings.planUndoHistory||[]).length?`<button class="btn danger" data-act="undo-last-replan">Undo last accepted replan</button>`:''}<button class="btn primary" data-act="smart-replan-programme" data-id="${pid}">Review recommended programme schedule</button>`:`<label class="mode-inline">Planning mode<select id="portfolioPlanningMode">${['Auto','Assisted','Manual'].map(x=>`<option ${x===mode?'selected':''}>${x}</option>`).join('')}</select></label>${(state.settings.planUndoHistory||[]).length?`<button class="btn danger" data-act="undo-last-replan">Undo last accepted replan</button>`:''}<button class="btn primary" data-act="smart-replan-portfolio">Review recommended lab schedule</button>`}</div></div>`;return base.replace(/<div class="page-head">[\s\S]*?<\/div><\/div>/,m=>m)+expl;}

