function guidedWorkflowButton(item){const [act,icon,title,desc]=item;if(String(act).startsWith('route:')){const r=String(act).slice(6);return`<button class="workflow-option" data-route-jump="${esc(r)}"><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;}if(act==='help-open'||act==='help-section')return`<button class="workflow-option" data-route-jump="help"><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;if(act==='jump-route-resources')return`<button class="workflow-option" data-route-jump="resources"><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;if(act==='jump-route-analytics')return`<button class="workflow-option" data-route-jump="analytics"><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;if(act==='open-project-plan'){const id=state.settings.planningProject||state.programmes[0]?.id||'';return`<button class="workflow-option" data-act="open-project-plan" data-id="${id}"><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;}if(act==='smart-replan-programme'){const id=state.settings.planningProject||state.programmes.find(p=>['Blocked','Late','At Risk'].includes(p.scheduleRisk))?.id||state.programmes[0]?.id||'';return`<button class="workflow-option" data-act="smart-replan-programme" data-id="${id}"><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;}if(act==='guided-next-unscheduled'){const pid=state.settings.planningProject||'',l=state.legs.find(x=>(!pid||x.programmeId===pid)&&x.status!=='Completed'&&!x.plannedStart);return`<button class="workflow-option" ${l?`data-act="guided-blocker" data-id="${l.id}"`:'disabled'}><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;}if(act==='auto-report-first'){const l=state.legs.find(x=>x.status==='Completed')||state.legs[0];return`<button class="workflow-option" ${l?`data-act="auto-report" data-id="${l.id}"`:'disabled'}><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;}return`<button class="workflow-option" data-act="${act}"><b>${icon}</b><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;}
function injectGuidedWorkflowLauncher(){const d=guidedWorkflowDefinition(),head=main.querySelector('.page-head');if(!d||!head)return;const pid=state.settings.planningProject||'',attention=route==='planning'&&state.legs.some(l=>(!pid||l.programmeId===pid)&&l.status!=='Completed'&&!l.plannedStart);head.insertAdjacentHTML('afterend',`<details class="workflow-assistant card" ${attention?'open':''}><summary><div><span class="workflow-assistant-icon">→</span><strong>${esc(d.title)}</strong><small>Guided actions · every blocked path should lead to a resolvable next step</small></div><span class="fold-chevron">⌄</span></summary><div class="workflow-option-grid">${d.items.map(guidedWorkflowButton).join('')}</div></details>`);}
function applyProgressiveDisclosure(){const compact=matchMedia('(max-width: 760px)').matches,sections=[...main.querySelectorAll('section.card')];let count=0;for(const s of sections){const h=s.querySelector(':scope > .section-title');if(!h||s.closest('.workflow-assistant')||s.classList.contains('live-channel'))continue;const title=h.querySelector('h2,h3');if(!title)continue;count++;const keepOpen=count<=2||/Actionable|Programme readiness|Planning intelligence|Decision & improvement|Execution-ready|Visual Validation Flow/i.test(title.textContent||'');s.classList.add('foldable-section');if((compact&&!keepOpen)||(!compact&&count>4))s.classList.add('collapsed');if(!h.querySelector('.section-fold-toggle')){const b=document.createElement('button');b.className='section-fold-toggle';b.type='button';b.setAttribute('aria-label','Expand or collapse section');b.innerHTML='<span>⌄</span>';b.onclick=e=>{e.preventDefault();e.stopPropagation();s.classList.toggle('collapsed')};h.appendChild(b);}}}
function renderHelp(){return pageHead('Help & User Manual','Task-based guidance for LabOS. Start with what you are trying to accomplish, then follow the evidence-gated workflow.',`<a class="btn primary" href="LabOS-User-Manual.html" target="_blank" rel="noopener">Open full manual ↗</a><a class="btn" href="LabOS-Quick-Start.html" target="_blank" rel="noopener">Quick start ↗</a>`)+`<div class="help-hero card"><div><span class="eyebrow">GUIDED OPERATIONS</span><h2>LabOS should never leave you at a warning with no next action.</h2><p>Every operational state is treated as a workflow: understand → act → prove → recheck → continue. The manual uses real prototype screenshots and worked examples.</p></div><div class="help-flow"><span>1 Understand</span><i>→</i><span>2 Act</span><i>→</i><span>3 Evidence</span><i>→</i><span>4 Replan / continue</span></div></div><div class="help-topic-grid"><a class="help-topic" href="LabOS-User-Manual.html#prototype" target="_blank"><b>◇</b><strong>Prototype build</strong><span>Request, material ready, link to programme/leg/test, build evidence, delay and protected replanning.</span></a><a class="help-topic" href="LabOS-User-Manual.html#validation" target="_blank"><b>◫</b><strong>Validation plan</strong><span>Samples and serials, visual test flow, recursive branches, readiness and scheduling.</span></a><a class="help-topic" href="LabOS-User-Manual.html#planning" target="_blank"><b>▤</b><strong>Planning & blockers</strong><span>What happens when scheduling cannot complete and how to resolve each blocker.</span></a><a class="help-topic" href="LabOS-User-Manual.html#reporting" target="_blank"><b>▣</b><strong>Test reporting</strong><span>Test/leg/programme reports, customer/internal presets, anonymisation and approval.</span></a><a class="help-topic" href="LabOS-User-Manual.html#quality" target="_blank"><b>◆</b><strong>Quality & learning</strong><span>From evidence to proposal, implementation and effectiveness verification.</span></a><a class="help-topic" href="LabOS-User-Manual.html#troubleshooting" target="_blank"><b>?</b><strong>Common blocker guide</strong><span>Samples, custody, development, calibration, people, equipment, specs and dependencies.</span></a></div>${section('In-app guided entry points',`<div class="manual-checklist"><div><b>Validation</b><span>New programme → samples → flow → readiness → schedule</span></div><div><b>Prototype</b><span>Request → material → build → evidence → release → linked replan</span></div><div><b>Planning</b><span>Calculate → resolve blockers → recalculate → compare → accept/reject → undo</span></div><div><b>Execution</b><span>Readiness → LES → live data → result/evidence → report → approval</span></div><div><b>Quality</b><span>Signal → correlated case → proposal → implement → prove effectiveness</span></div></div>`,'Use the foldout “Guided workflow” at the top of each main workspace.')}`;}
function render(){ensureV114Styles();recomputeRequirementStatuses(state);const views={dashboard:renderHomeV100,validation:renderProgrammesV100,programmes:renderProgrammesV100,programme:renderProgrammeWorkspace,prototyping:renderPrototypes,prototypes:renderPrototypes,testportfolio:renderTestPortfolio,planning:renderPlanningV100,execution:renderExecutionHub,quality:renderQualityHub,lab:renderLabV100,insights:renderInsightsV100,help:renderHelp,resources:renderResourcesHub,metrologyservice:renderMetrologyService,analytics:renderAnalyticsHub,audit:renderAudit,admin:renderAdmin,builder:renderBuilder,requirements:renderRequirements,specifications:renderSpecifications,custody:renderCustody,guided:renderGuided,live:renderLive,control:renderControl,duts:renderDUTs,library:renderLibrary,equipment:renderEquipment,calibration:renderCalibration,metrology:renderMetrology,materials:renderMaterials,external:renderExternal,people:renderPeople,costs:renderCosts,capacity:renderCapacity,twin:renderTwin,knowledge:renderKnowledge,maintenance:renderMaintenance};main.innerHTML=(views[route]||renderDashboard)();injectGuidedWorkflowLauncher();wireRoute();applyProgressiveDisclosure();}
function renderDashboard(){const vd=filteredDashboardData(),K=kpis(vd),p=periodRange(),PM=periodMetrics(vd,p.start,p.end),TR=periodTrend(vd,p.start,p.end),IA=issueAnalytics(vd,p.start,p.end),bn=bottlenecks(vd),CP=portfolioCost(vd),cf=capacityForecast(state,12,state.settings.pipelineMode||'weighted'),AP=auditPortfolio(state),MS=maintenanceSummary(state,60),E=efficiencyMetrics(vd,p.start,p.end),recs=operationalRecommendations(state),syn=serviceSynergy(state,120),auditReady=AP.avg,peakEq=Math.max(0,...cf.weeks.map(x=>x.equipmentUnitsGap)),peakFte=Math.max(0,...cf.weeks.map(x=>x.staffFteGap)),portfolioLate=vd.programmes.filter(x=>['Late','At Risk','Blocked'].includes(x.scheduleRisk)).length,openAlerts=state.liveAlerts.filter(a=>a.status==='Open').length;
 return pageHead('Laboratory Operations Command Center',`Delivery, validation assurance, live execution, efficiency, learning, cost, capacity and asset health · ${state.settings.role||'Lab Manager'} view`,`<button class="btn" data-act="report-issue">＋ Log Issue</button><button class="btn" data-act="jump-live">◉ Live Tests</button><button class="btn primary" data-act="smart-replan-portfolio">↻ Recalculate all lab schedules</button>`)+periodControls()+dashboardFilterBar()+`<div class="command-strip command-strip-6"><button class="command-health kpi-drill ${portfolioLate?'risk':'good'}" data-act="kpi-drill" data-id="delivery"><span>Portfolio delivery</span><strong>${K.onTimePct}%</strong><small>${portfolioLate} programmes at risk / late / blocked · tap for projects</small></button><button class="command-health kpi-drill ${K.criticalOutstanding?'risk':'good'}" data-act="kpi-drill" data-id="assurance"><span>Validation assurance</span><strong>${K.reqVerified}%</strong><small>${K.criticalOutstanding} critical requirements outstanding · tap for gaps</small></button><button class="command-health kpi-drill ${E.productiveTestPct<55?'risk':'good'}" data-act="kpi-drill" data-id="productive"><span>Productive test time</span><strong>${E.productiveTestPct}%</strong><small>direct execution / total cycle incl. queue · tap for methods</small></button><button class="command-health kpi-drill ${openAlerts?'risk':'good'}" data-act="kpi-drill" data-id="live"><span>Live execution alerts</span><strong>${openAlerts}</strong><small>${state.liveSessions.filter(s=>s.status==='Streaming').length} streaming test sessions · tap for events</small></button><button class="command-health kpi-drill ${CP.variance>0?'risk':'good'}" data-act="kpi-drill" data-id="finance"><span>Financial control</span><strong>${currency(vd,CP.totalForecast,true)}</strong><small>${CP.variance>0?`${currency(vd,CP.variance,true)} above budget`:'within portfolio budget'} · tap for programmes</small></button><button class="command-health kpi-drill ${peakEq||peakFte?'risk':'good'}" data-act="kpi-drill" data-id="capacity"><span>12-week resource outlook</span><strong>${peakEq} assets / ${peakFte} FTE</strong><small>peak incremental weighted-pipeline need · tap for constraints</small></button></div><div class="grid kpi visual-kpis exec-kpis">${drillKpiCard('First-time-right',`${E.firstTimeRightPct}%`,`${PM.failed} fail · ${PM.rework} rework`,'ftr')}${drillKpiCard('Queue loss',`${E.queueLossPct}%`,'Waiting inside test cycle','queue')}${drillKpiCard('Setup burden',`${E.setupPct}%`,'Setup share of actual cycle','setup')}${drillKpiCard('Automation leverage',`${E.automationLeveragePct}%`,'Unattended-capable execution','automation')}${drillKpiCard('Issue impact',`${PM.issueDelayHours}h`,`${PM.issues} issues · ${PM.specIssuePct}% spec-driven`,'issues')}${drillKpiCard('Audit readiness',`${auditReady}%`,`${AP.open} open findings`,'audit')}${drillKpiCard('Service bundling',syn.filter(x=>x.combine).length,`${syn.reduce((a,x)=>a+x.avoidedDowntimeHours,0)}h avoidable downtime`,'service')}${drillKpiCard('Development efficiency',`${E.developmentEfficiencyPct}%`,'estimated / actual effort','development')}</div><div class="grid dashboard-command-grid"><section class="card command-large"><div class="section-title"><h2>12-week demand vs resource capacity</h2><span class="hint">Committed + probability-weighted pipeline</span></div>${forecastDemandViz(cf,'equipment')}<div class="capacity-alerts"><div><strong>${cf.equipmentGapWeeks}</strong><span>equipment-gap weeks</span></div><div><strong>${cf.staffGapWeeks}</strong><span>staff-gap weeks</span></div><div><strong>${peakEq}</strong><span>extra assets</span></div><div><strong>${peakFte}</strong><span>FTE peak gap</span></div></div><div class="actions"><button class="btn small" data-act="jump-capacity">Open Capacity Plan</button></div></section><section class="card command-side"><div class="section-title"><h2>Efficiency pulse</h2></div><div class="efficiency-dials"><div><strong>${E.productiveTestPct}%</strong><span>productive test</span></div><div><strong>${E.firstTimeRightPct}%</strong><span>first-time-right</span></div><div><strong>${E.handsOnPct}%</strong><span>hands-on ratio</span></div><div><strong>${E.reworkBurdenPct}%</strong><span>rework burden</span></div></div><div class="actions"><button class="btn small" data-route-jump="analytics">Open Test Intelligence</button></div></section></div><div class="grid section-grid equal" style="margin-top:14px">${section('Delivery & issue trend',trendViz(TR),`Selected period · ${TR.mode} buckets`)}${section('Outcome and root-cause profile',outcomeViz(PM)+rootCauseDonut(IA.rootCauses),'Root cause feeds traceable lessons learned')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Automated bottleneck / issue solutions',`<div class="decision-list">${recs.slice(0,8).map(r=>`<div><span class="decision-icon">${r.type==='Capacity'?'▥':r.type==='Asset service'?'⚙':'!'}</span><div><strong>${esc(r.title)}</strong><p>${esc(r.detail)} <b>Proposed solution:</b> ${esc(r.solution)}</p><small>${esc(r.impact)} · ${r.confidence} confidence</small>${r.action?`<button class="btn small" data-act="recommendation-action" data-id="${r.id}">Apply / Review</button>`:''}</div></div>`).join('')}</div>`,'Prioritised from capacity, recurring issues, asset service and learned test-time drift')}${section('Live laboratory status',`<div class="list">${state.liveSessions.map(s=>{const q=liveSessionSummary(state,s),l=state.legs.find(x=>x.id===s.legId);return`<div class="list-row"><div><strong>${s.id} · ${l?.id||s.legId} · ${esc(l?.name||'')}</strong><small>${s.sourceType} · ${q.points} data points · ${q.open} open alerts</small></div><button class="btn small" data-act="open-live-session" data-id="${s.id}">${s.status}</button></div>`}).join('')}</div>`,'Engineer-facing live data and anomaly alerts')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Top future equipment needs',gapTable(cf.equipment,'equipment'),'Committed + weighted pipeline')}${section('Top future staffing / skill needs',gapTable(cf.staff,'staff'),'Qualified-resource demand')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Portfolio delivery heat',programmeRows(vd.programmes.slice().sort((a,b)=>priorityRank[b.priority]-priorityRank[a.priority]||new Date(a.dueDate)-new Date(b.dueDate)),vd),'Active projects')}${section('Priority scenario comparison',scenarioCards(),'Compare project prioritisation before applying')}</div>`;}
function dashboardFilterBar(){const f=state.settings.dashboardFilters||{};const customers=[...new Set(state.programmes.map(p=>p.customer))].sort(),cats=[...new Set(state.methods.map(m=>m.category))].sort();return `<div class="filters"><select id="dashProgramme"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}" ${f.programme===p.id?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select><select id="dashCustomer"><option value="">All customers</option>${customers.map(x=>`<option ${f.customer===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="dashCategory"><option value="">All test categories</option>${cats.map(x=>`<option ${f.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="dashPriority"><option value="">All priorities</option>${['Critical','High','Normal','Low'].map(x=>`<option ${f.priority===x?'selected':''}>${x}</option>`).join('')}</select><select id="dashStatus"><option value="">All risk states</option>${['On Track','At Risk','Late','Blocked'].map(x=>`<option ${f.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="dashEquipment"><option value="">All equipment</option>${state.equipment.map(e=>`<option value="${e.id}" ${f.equipment===e.id?'selected':''}>${e.id}</option>`).join('')}</select><select id="dashStaff"><option value="">All staff</option>${state.staff.map(x=>`<option value="${x.id}" ${f.staff===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`}
function filteredDashboardData(){const f=state.settings.dashboardFilters||{};let programs=state.programmes.filter(p=>(!f.programme||p.id===f.programme)&&(!f.customer||p.customer===f.customer)&&(!f.priority||p.priority===f.priority)&&(!f.status||p.scheduleRisk===f.status));const pids=new Set(programs.map(p=>p.id));let methods=state.methods.filter(m=>!f.category||m.category===f.category),mids=new Set(methods.map(m=>m.id));let legs=state.legs.filter(l=>pids.has(l.programmeId)&&mids.has(l.methodId)&&(!f.equipment||l.equipmentId===f.equipment)&&(!f.staff||l.staffId===f.staff));const legIds=new Set(legs.map(l=>l.id));if(f.category||f.equipment||f.staff){const usedPids=new Set(legs.map(l=>l.programmeId));programs=programs.filter(p=>usedPids.has(p.id));}const finalPids=new Set(programs.map(p=>p.id));const requirements=state.requirements.filter(r=>finalPids.has(r.programmeId));const bookings=state.bookings.filter(b=>legIds.has(b.legId)&&(!f.equipment||b.equipmentId===f.equipment)&&(!f.staff||b.staffId===f.staff));const equipment=f.equipment?state.equipment.filter(e=>e.id===f.equipment):state.equipment;const staff=f.staff?state.staff.filter(s=>s.id===f.staff):state.staff;const testRuns=(state.testRuns||[]).filter(r=>finalPids.has(r.programmeId)&&mids.has(r.methodId)&&(!f.equipment||r.equipmentId===f.equipment)&&(!f.staff||r.staffId===f.staff));const runIds=new Set(testRuns.map(r=>r.id));const issues=(state.issues||[]).filter(i=>finalPids.has(i.programmeId)&&(!i.testRunId||runIds.has(i.testRunId)));return {...state,programmes:programs,requirements,methods,legs,duts:state.duts.filter(d=>finalPids.has(d.programmeId)),bookings,equipment,staff,devTasks:state.devTasks.filter(d=>finalPids.has(d.programmeId)),specifications:(state.specifications||[]).filter(x=>finalPids.has(x.programmeId)),testRuns,issues,disruptions:(state.disruptions||[]).filter(d=>finalPids.has(d.programmeId))};}

function programmeRows(programmes,data=state){return `<div class="table-wrap"><table><thead><tr><th>Programme</th><th>Project</th><th>Priority</th><th>Due</th><th>Forecast</th><th>Risk</th><th>Progress</th></tr></thead><tbody>${programmes.map(p=>{const ls=data.legs.filter(l=>l.programmeId===p.id),done=ls.filter(l=>l.status==='Completed').length;return `<tr><td><span class="link mono" data-entity="programme" data-id="${p.id}">${p.id}</span></td><td><strong>${esc(p.project)}</strong><div class="muted small">${esc(p.product)}</div></td><td>${pill(p.priority)}</td><td>${fmtDate(p.dueDate)}</td><td>${fmtDate(p.forecastCompletion)}</td><td>${pill(p.scheduleRisk||'Unplanned')}</td><td><div class="bar-head"><span>${done}/${ls.length}</span><span>${pct(done,ls.length)}%</span></div><div class="progress"><span style="width:${pct(done,ls.length)}%"></span></div></td></tr>`}).join('')}</tbody></table></div>`}
