function createIntelligenceQualityEvent(c){let q=(state.qualityEvents||[]).find(x=>x.sourceType==='Intelligence'&&x.sourceId===c.id&&x.status!=='Closed');if(q)return q;const issue=(c.signals?.issues||[]).map(id=>state.issues.find(x=>x.id===id)).find(Boolean);if(issue&&c.kind==='live'){q=qualityEventFromIssue(state,issue.id);if(q)return q;}let num=state.qualityEvents.length+1,id=`QE-${String(num).padStart(3,'0')}`;while(state.qualityEvents.some(x=>x.id===id)){num++;id=`QE-${String(num).padStart(3,'0')}`;}q={id,type:c.kind==='learning'?'Continuous Improvement':'Investigation',sourceType:'Intelligence',sourceId:c.id,programmeId:c.programmeId||'',legId:c.legId||'',dutIds:(state.legs.find(l=>l.id===c.legId)?.dutIds||[]).slice(0,3),severity:c.severity==='Critical'||c.severity==='High'?'Major':'Minor',status:'Containment',detectedAt:new Date().toISOString(),owner:state.settings.actor||'Demo Lab Manager',containment:c.proposalType==='integrated_investigation'?'Contain affected work and preserve correlated evidence.':'No additional containment unless current work is affected.',investigationMethod:'Evidence correlation + 5 Why',rootCause:c.kind==='learning'?(issue?.rootCause||c.hypothesis):'Under investigation',disposition:'Pending controlled decision',dueDate:dayISO(7),effectivenessStatus:'Pending'};state.qualityEvents.push(q);return q;}
