 const a=state.settings.planningAdvisor;a.rejected=a.rejected||[];a.decisions=a.decisions||[];a.approvedActions=a.approvedActions||[];a.intervalSeconds=Math.max(30,Number(a.intervalSeconds)||60);return a;
