 planningAdvisorTimer=setInterval(()=>{if(document.hidden||!state||planningAdvisorStore().enabled===false)return;const before=(planningAdvisorCache?.suggestions||[]).map(x=>x.id).join('|'),next=filteredPlanningAdvisorBundle(true),after=(next.suggestions||[]).map(x=>x.id).join('|');if(['planning','dashboard'].includes(route)&&before!==after)render();},seconds*1000);
