function advisorImpactRows(s){const moves={};for(const d of s.diff||[]){moves[d.programmeId]=(moves[d.programmeId]||0)+1}const ids=new Set([...(s.impacts||[]).map(x=>x.programmeId),...Object.keys(moves)]);return [...ids].map(id=>{const p=state.programmes.find(x=>x.id===id),n=s.candidateData.programmes.find(x=>x.id===id)||p,oldF=p?.forecastCompletion?new Date(p.forecastCompletion):null,newF=n?.forecastCompletion?new Date(n.forecastCompletion):null,due=n?.dueDate?new Date(n.dueDate):null,deltaDays=oldF&&newF?Math.round(((newF-oldF)/86400000)*10)/10:0,lateDays=due&&newF?Math.round(Math.max(0,(newF-due)/86400000)*10)/10:0;return{programmeId:id,project:p?.project||'',oldForecast:p?.forecastCompletion||null,newForecast:n?.forecastCompletion||null,deltaDays,moves:moves[id]||0,oldRisk:p?.scheduleRisk||p?.status,newRisk:n?.scheduleRisk||n?.status,dueDate:n?.dueDate||p?.dueDate,lateDays}})}
