function planningDecisionSeverity(g){const rank={Low:1,Medium:2,High:3,Critical:4};let best='Low';for(const d of g.rows){for(const id of [...(d.sourceIssueIds||[]),...(d.sourceIssueId?[d.sourceIssueId]:[])]){const i=(state.issues||[]).find(x=>x.id===id);if(i&&(rank[i.severity]||0)>(rank[best]||0))best=i.severity}}return best}
