function planningStaffRows(){const pid=state.settings.planningProject||'',cfg=planningScaleConfig(),end=new Date(DEMO_NOW.getTime()+cfg.days*86400000),rows=state.staff.map(s=>{const bs=state.bookings.filter(b=>(!pid||b.programmeId===pid)&&b.staffId===s.id&&new Date(b.start)<end&&new Date(b.staffEnd||b.end)>DEMO_NOW).sort((a,b)=>new Date(a.start)-new Date(b.start)),hours=bs.reduce((sum,b)=>sum+(new Date(b.staffEnd||b.end)-new Date(b.start))/3600000,0);return{s,bs,hours}}).filter(x=>x.bs.length).sort((a,b)=>b.hours-a.hours);return `<div class="table-wrap"><table><thead><tr><th>Staff</th><th>Role</th><th>Booked attended hours</th><th>Allocations in ${cfg.label.toLowerCase()} view</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="link" data-entity="staff" data-id="${x.s.id}">${esc(x.s.name)}</span></td><td>${esc(x.s.role)}</td><td>${x.hours.toFixed(1)}h</td><td>${x.bs.slice(0,20).map(b=>`${b.legId} · ${fmtDate(b.start,true)}`).join('<br>')}${x.bs.length>20?`<br><span class="small muted">+${x.bs.length-20} more</span>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
