 if(!point)return toast('No accepted replan is available to undo.');
 const linkedActionId=point.governanceActionId||null;
 restorePlanningPoint(point);
 if(linkedActionId){const a=decisionIntelligenceStore().actions.find(x=>x.id===linkedActionId);if(a){a.status='Undone';a.undoneAt=new Date().toISOString();a.verificationSummary='Controlled planning change was undone; implementation/effectiveness workflow cancelled.';}}
