 await persist();render();
 planningAdvisorCache=null;openModal(`<h2>Planning change undone</h2><div class="callout warning"><strong>The previous planning state has been restored.</strong><p>Bookings, resource preferences and optimizer-controlled calibration/decision changes were restored. Any real-world delay or disruption records remain active, so LabOS has marked planning as needing review.</p></div><div class="actions"><button class="btn primary" data-act="smart-replan-portfolio">Review schedule again</button><button id="closeUndoModal" class="btn">Close</button></div>`);wireModalActions();document.getElementById('closeUndoModal').onclick=closeModal;
