function reportIssueModal(prefProgramme='',prefLeg=''){const activeLegs=state.legs.filter(l=>!['Completed','Cancelled','Failed'].includes(l.status)),prefP=prefProgramme||state.legs.find(l=>l.id===prefLeg)?.programmeId||state.settings.planningProject||state.programmes[0]?.id||'';openModal(`<h2>Log Delay / Test Issue</h2><p class="small muted">Log the operational event first. LabOS will then let you compare a protected programme-only recovery with a portfolio-aware recovery that may flex selected competing programmes.</p><div class="modal-grid"><div class="field"><label>Event type</label><select id="issType"><option value="sample_delay">Sample / DUT delay</option><option value="test_issue">Test execution issue</option><option value="equipment_issue">Equipment outage / interruption</option><option value="spec_issue">Bad / ambiguous specification</option><option value="resource_issue">Staff / qualification issue</option></select></div><div class="field"><label>Programme</label><select id="issProg">${state.programmes.map(p=>`<option value="${p.id}" ${p.id===prefP?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select></div><div class="field"><label>Affected test leg</label><select id="issLeg"><option value="">Programme-level</option>${activeLegs.map(l=>`<option value="${l.id}" data-prog="${l.programmeId}" ${l.id===prefLeg?'selected':''}>${l.id} · ${l.programmeId} · ${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Equipment (if applicable)</label><select id="issEq"><option value="">None / not equipment-specific</option>${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Specification (if applicable)</label><select id="issSpec"><option value="">None</option>${state.specifications.map(sp=>`<option value="${sp.id}">${sp.id} Rev ${esc(sp.revision)} · ${esc(sp.name)}</option>`).join('')}</select></div><div class="field"><label>Severity / escalation level</label><select id="issSeverity">${['Low','Medium','High','Critical'].map(x=>`<option ${x==='Medium'?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Constraint / recovery until</label><input id="issUntil" type="datetime-local" value="${dayISO(3,12).slice(0,16)}"></div><div class="field"><label>Estimated delay impact (hours)</label><input id="issHours" type="number" min="0" step="1" value="24"></div></div><div class="field"><label>Issue description</label><textarea id="issDesc">Sample / test condition changed; planner must account for the new availability constraint.</textarea></div><div class="field"><label>Issue subtype</label><input id="issSubtype" value="Sample arrival delay"></div><div class="callout"><strong>Controlled replanning:</strong> after saving, LabOS calculates the alternatives without changing the current schedule. You explicitly accept or reject the impact, and every accepted replan gets an Undo point.</div><div class="actions" style="margin-top:14px"><button id="saveIssue" class="btn">Save delay only</button><button id="saveIssueReview" class="btn primary">Save delay & review replanning options →</button></div>`);const sync=()=>{const t=document.getElementById('issType').value,sub=document.getElementById('issSubtype'),desc=document.getElementById('issDesc');const map={sample_delay:['Sample arrival delay','Customer sample/DUT availability changed.'],test_issue:['Fixture / connection problem','Test execution issue requires recovery or repeat work.'],equipment_issue:['Equipment interruption','Equipment is unavailable until recovery.'],spec_issue:['Specification ambiguity','Specification ambiguity or missing acceptance criterion identified.'],resource_issue:['Qualification / staffing gap','Required competent resource is unavailable.']};sub.value=map[t][0];desc.value=map[t][1]};document.getElementById('issType').onchange=sync;const prog=document.getElementById('issProg'),legSel=document.getElementById('issLeg'),specSel=document.getElementById('issSpec');const filter=()=>{for(const o of [...legSel.options])if(o.value)o.hidden=o.dataset.prog!==prog.value;if(legSel.value&&legSel.selectedOptions[0]?.hidden)legSel.value='';for(const o of [...specSel.options])if(o.value)o.hidden=state.specifications.find(x=>x.id===o.value)?.programmeId!==prog.value;if(specSel.value&&specSel.selectedOptions[0]?.hidden)specSel.value=''};prog.onchange=filter;filter();if(prefLeg)legSel.value=prefLeg;const save=async(review)=>{const type=document.getElementById('issType').value,pid=prog.value,legId=legSel.value||null,eqId=document.getElementById('issEq').value||null,specId=document.getElementById('issSpec').value||null,severity=document.getElementById('issSeverity').value,untilRaw=document.getElementById('issUntil').value,hours=Math.max(0,Number(document.getElementById('issHours').value)||0),description=document.getElementById('issDesc').value.trim(),issueType=document.getElementById('issSubtype').value.trim()||'Operational issue';if(!description)return toast('Describe the issue.');if(type==='equipment_issue'&&!eqId)return toast('Select the affected equipment for an equipment outage.');if(type!=='spec_issue'&&!untilRaw)return toast('Set the recovery / constraint end time.');const untilDate=untilRaw?new Date(untilRaw):null;if(untilDate&&Number.isNaN(untilDate.getTime()))return toast('Enter a valid recovery time.');const until=untilDate?untilDate.toISOString():null,rootCause=type==='spec_issue'?'Bad Specification':type==='sample_delay'?'Sample / DUT':type==='equipment_issue'?'Equipment / Facility':type==='resource_issue'?'Planning / Resource':'Test Execution',lesson=rootCause==='Bad Specification'?'Add a specification completeness/ambiguity gate before test release':rootCause==='Test Execution'?'Standardise pre-test setup checks and capture recurrent execution failure modes':rootCause==='Sample / DUT'?'Make confirmed sample-ready date a hard planning input':'Expose resource interruptions immediately and maintain contingency capacity',iid=`ISS-${String((state.issues||[]).length+1).padStart(3,'0')}`,issue={id:iid,reportedAt:new Date().toISOString(),programmeId:pid,legId,testRunId:null,specificationId:specId,issueType,rootCause,severity,delayHours:hours,status:'Open',description,lesson,correctiveAction:lesson,owner:state.settings.actor};state.issues.push(issue);if(type!=='spec_issue'){const dtype=type==='resource_issue'?'test_issue':type;state.disruptions.push({id:`DSP-${String((state.disruptions||[]).length+1).padStart(3,'0')}`,type:dtype,status:'Active',programmeId:pid,legId,equipmentId:type==='equipment_issue'?eqId:null,reportedAt:new Date().toISOString(),effectiveUntil:until,reason:description,impactHours:hours,sourceIssueId:iid});state.settings.planDirty=true}if(specId&&rootCause==='Bad Specification'){const sp=state.specifications.find(x=>x.id===specId);if(sp){sp.qualityScore=Math.max(0,(Number(sp.qualityScore)||80)-5);sp.qualityFlags=[...new Set([...(sp.qualityFlags||[]),issueType])]}}recordOperationalIssueEvent(state,issue,{replanScope:'Approval required'});detectRecurringLessons(state);state.audit.push(audit('Operational issue logged',iid,'',`${rootCause} · ${severity} · ${hours}h · schedule unchanged pending approval`));await persist();closeModal();render();if(review&&type!=='spec_issue')setTimeout(()=>delayReplanOptionsModal(iid,pid),0);else toast(review?`${iid} saved. Specification issue logged; no time-based replan was forced.`:`${iid} saved; current schedule retained and planning marked for review.`)};document.getElementById('saveIssue').onclick=()=>save(false);document.getElementById('saveIssueReview').onclick=()=>save(true)}

function resolveDisruption(id){const d=(state.disruptions||[]).find(x=>x.id===id);if(!d)return;openModal(`<h2>Close Planning Constraint · ${d.id}</h2><div class="callout warning"><strong>Resolution requires evidence.</strong><p>A planning constraint is only released after the recovery action and evidence/reference are recorded. This creates an auditable closure trail.</p></div><div class="field"><label>Recovery / corrective action</label><textarea id="rdAction" placeholder="What was done to remove the constraint?"></textarea></div><div class="field"><label>Objective evidence / reference</label><textarea id="rdEvidence" placeholder="e.g. sample receipt GRN-2041, repair WO-1138, rerun report TR-0097, supplier confirmation..."></textarea></div><div class="field"><label>Verified by</label><select id="rdVerifier">${state.staff.map(s=>`<option value="${s.name}">${esc(s.name)} · ${esc(s.role)}</option>`).join('')}</select></div><button id="confirmResolveDisruption" class="btn primary">Verify Evidence & Close Constraint</button>`);document.getElementById('confirmResolveDisruption').onclick=async()=>{const action=document.getElementById('rdAction').value.trim(),evidence=document.getElementById('rdEvidence').value.trim(),verifier=document.getElementById('rdVerifier').value;if(!action||!evidence)return toast('Recovery action and objective evidence are both required.');const priorStatus=d.status;d.status='Resolved';d.resolvedAt=new Date().toISOString();d.resolution={action,evidence,verifiedBy:verifier,verifiedAt:d.resolvedAt};const i=(state.issues||[]).find(x=>x.id===d.sourceIssueId);if(i){i.status='Closed';i.closureEvidence=[...(i.closureEvidence||[]),{action,evidence,verifiedBy:verifier,timestamp:d.resolvedAt}];}state.settings.planDirty=true;state.audit.push(audit('Planning disruption evidence-closed',id,priorStatus,`${action} · ${evidence}`));await persist();closeModal();render();toast(`${id} evidence verified and closed. Update the plan to release the constraint.`)}}

function scenarioPanel(){return `<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Scenario</label><select id="scenarioType"><option value="equipment_unavailable">Equipment unavailable for 7 days</option><option value="staff_unavailable">Staff unavailable next week</option><option value="add_equipment">Add temporary thermal chamber</option></select></div><div class="field" id="scenarioTargetWrap"><label>Target</label><select id="scenarioTarget">${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="actions"><button class="btn primary" data-act="apply-scenario">Apply & Replan</button>${state.settings.scenario?'<button class="btn" data-act="reset-scenario">Reset Scenario</button>':''}</div>${state.settings.scenario?`<div class="callout warning" style="margin-top:12px"><strong>Active:</strong> ${esc(state.settings.scenario.label||state.settings.scenario.type)}</div>`:''}</div>`}

function wireRoute(){wireEntities(main);for(const b of main.querySelectorAll('[data-act]'))b.addEventListener('click',handleAction);for(const b of main.querySelectorAll('[data-route-jump]'))b.addEventListener('click',()=>go(b.dataset.routeJump));for(const b of main.querySelectorAll('[data-booking]'))b.addEventListener('click',()=>showBooking(b.dataset.booking));if(route==='dashboard'){for(const x of ['dashProgramme','dashCustomer','dashCategory','dashPriority','dashStatus','dashEquipment','dashStaff']){const el=document.getElementById(x);if(el)el.addEventListener('change',async()=>{state.settings.dashboardFilters={programme:document.getElementById('dashProgramme').value,customer:document.getElementById('dashCustomer').value,category:document.getElementById('dashCategory').value,priority:document.getElementById('dashPriority').value,status:document.getElementById('dashStatus').value,equipment:document.getElementById('dashEquipment').value,staff:document.getElementById('dashStaff').value};await persist();render();});}wirePeriodControls()}if(route==='analytics'||route==='insights')wirePeriodControls();if(route==='live'){for(const b of main.querySelectorAll('[data-live-session]'))b.onclick=async()=>{state.settings.liveSession=b.dataset.liveSession;await persist();render()};startLiveTicker();}if(route==='requirements'){for(const x of ['reqProg','reqStatus','reqCrit','reqCategory','reqAttention','reqFilter'])document.getElementById(x)?.addEventListener('input',renderReqTable);renderReqTable()}if(route==='specifications'){for(const x of ['specProg','specStatus','specAttention','specFilter'])document.getElementById(x)?.addEventListener('input',renderSpecTable);renderSpecTable()}if(route==='duts'){for(const x of ['dutProg','dutStatus','dutFilter'])document.getElementById(x).addEventListener('input',renderDutTable);renderDutTable()}if(route==='programmes'){for(const s of main.querySelectorAll('.priority-change'))s.addEventListener('change',()=>changePriority(s.dataset.id,s.value))}if(route==='planning'){const pp=document.getElementById('planningProject');if(pp)pp.onchange=async()=>{state.settings.planningProject=pp.value;await persist();render()};const f=document.getElementById('scenarioFocus');if(f)f.onchange=async()=>{state.settings.scenarioFocusProgramme=f.value;await persist();render()};const pm=document.getElementById('portfolioPlanningMode');if(pm)pm.onchange=async()=>{state.settings.portfolioPlanningMode=pm.value;state.audit.push(audit('Portfolio planning mode changed','Planning','',pm.value));await persist();render()}}if(route==='planning'){for(const b of main.querySelectorAll('.booking[draggable="true"]'))b.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',b.dataset.booking);e.dataTransfer.effectAllowed='move';b.classList.add('dragging')});for(const b of main.querySelectorAll('.booking[draggable="true"]'))b.addEventListener('dragend',()=>b.classList.remove('dragging'));for(const c of main.querySelectorAll('.gantt-cell[data-drop-eq]')){c.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move';c.classList.add('drop-target')});c.addEventListener('dragleave',()=>c.classList.remove('drop-target'));c.addEventListener('drop',e=>{e.preventDefault();c.classList.remove('drop-target');const id=e.dataTransfer.getData('text/plain');if(id)dropBookingOnTimeline(id,c.dataset.dropEq,c.dataset.dropDay)})}}if(route==='builder')wireBuilder();if(route==='costs'){const c=document.getElementById('costProgramme');if(c)c.onchange=async()=>{state.settings.costProgramme=c.value;await persist();render()}}if(route==='capacity'){const h=document.getElementById('capacityHorizon'),m=document.getElementById('pipelineMode');if(h)h.onchange=async()=>{state.settings.capacityHorizon=Number(h.value);await persist();render()};if(m)m.onchange=async()=>{state.settings.pipelineMode=m.value;await persist();render()}}if(route==='custody'){const c=document.getElementById('custodyProgramme');if(c)c.onchange=async()=>{state.settings.custodyProgramme=c.value;await persist();render()};}if(route==='twin'){const t=document.getElementById('twinProgramme');if(t)t.onchange=async()=>{state.settings.twinProgramme=t.value;await persist();render()};}if(route==='knowledge'){const k=document.getElementById('knowledgeProgramme');if(k)k.onchange=async()=>{state.settings.knowledgeProgramme=k.value;await persist();render()};}if(route==='audit'){const s=document.getElementById('auditStandard');if(s)s.onchange=async()=>{state.settings.auditStandard=s.value;state.settings.auditRecord='';await persist();render()};const ar=document.getElementById('auditRecord');if(ar)ar.onchange=async()=>{const a=state.audits.find(x=>x.id===ar.value);if(a){state.settings.auditStandard=a.standard;state.settings.auditRecord=a.id;await persist();render()}}}if(route==='admin'){const t=document.getElementById('scenarioType');if(t)t.onchange=updateScenarioTargets;updateScenarioTargets();}}
function wireEntities(root){for(const el of root.querySelectorAll('[data-entity]'))el.addEventListener('click',e=>{e.preventDefault();showEntity(el.dataset.entity,el.dataset.id)})}

function wireModalActions(){for(const b of modalBody.querySelectorAll('[data-act]'))b.addEventListener('click',handleAction);wireEntities(modalBody);}
async function builderAddMethod(methodId){
 const d=getBuilderDraft(),m=state.methods.find(x=>x.id===methodId);if(!m)return;normalizeBuilderTopology(d);if(!d.legs.length){const leg={id:`BL-${Date.now()}-${Math.floor(Math.random()*1000)}`,kind:'existing',methodId:m.id,legName:m.name,dutCount:Math.min(Number(d.dutCount)||8,m.dutCapacity||Number(d.dutCount)||8),populationMode:'Continue',dependencyMode:'Start',dependsOn:[],mainLegNo:1,stepNo:1,phase:'common',branchKey:'',branchGroup:'',mergeFrom:'',staffId:'',staffPolicy:'Auto'};d.legs.push(leg);normalizeBuilderTopology(d);await persist();render();return toast(`${m.id} added as the first test in Test Leg 1.`)}const lastNo=Math.max(...d.legs.map(builderMainLegNo)),active=builderBranchGroups(d).find(g=>g.mainLegNo===lastNo&&!g.merged),tails=builderMainLegTail(d,lastNo);if(active||tails.length!==1)return toast(`Choose a specific ${lastNo}a / ${lastNo}b branch and use “Add test below”, or merge the active branches first.`);const parent=tails[0],oldChildren=builderImmediateChildren(d,parent.id),step=(Number(parent.stepNo)||1)+1,leg={id:`BL-${Date.now()}-${Math.floor(Math.random()*1000)}`,kind:'existing',methodId:m.id,legName:m.name,dutCount:Math.min(Number(d.dutCount)||8,Number(parent.dutCount)||m.dutCapacity||Number(d.dutCount)||8),populationMode:'Continue',dependencyMode:'Custom',dependsOn:[parent.id],mainLegNo:lastNo,stepNo:step,phase:parent.phase||'common',branchKey:'',branchGroup:'',mergeFrom:'',staffId:'',staffPolicy:'Auto'};d.legs.push(leg);for(const child of oldChildren)child.dependsOn=(child.dependsOn||[]).map(id=>id===parent.id?leg.id:id);normalizeBuilderTopology(d);await persist();render();toast(`${m.id} added as another sequential test in Test Leg ${lastNo}.`)}
async function addPortfolioTestToBuilder(methodId){const d=getBuilderDraft(),m=state.methods.find(x=>x.id===methodId);if(!m)return;const last=d.legs.at(-1);d.legs.push({id:`BL-${Date.now()}-${Math.floor(Math.random()*1000)}`,kind:'existing',methodId:m.id,legName:m.name,dutCount:Math.min(Number(d.dutCount)||8,m.dutCapacity||Number(d.dutCount)||8),populationMode:'Continue',dependencyMode:last?'Custom':'Start',dependsOn:last?[last.id]:[],staffId:'',staffPolicy:'Auto'});state.audit.push(audit('Test added from portfolio','Programme Builder','',m.id));await persist();closeModal();go('builder');toast(`${m.id} added as the next validation leg.`)}
async function builderRemoveLeg(id){const d=getBuilderDraft();d.legs=d.legs.filter(x=>x.id!==id);for(const x of d.legs)x.dependsOn=(x.dependsOn||[]).filter(z=>z!==id);normalizeBuilderTopology(d);await persist();render();}
async function builderMoveLeg(id,dir){const d=getBuilderDraft(),i=d.legs.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=d.legs.length)return;[d.legs[i],d.legs[j]]=[d.legs[j],d.legs[i]];d.legs[0].dependencyMode='Start';await persist();render();}
function showLessonProvenance(methodId){const m=state.methods.find(x=>x.id===methodId),L=methodLessons(methodId);if(!m)return;openModal(`<h2>${m.id} · Lessons Learned Provenance</h2><div class="callout"><strong>${L.issues} source issues across ${L.runs} completed runs</strong><p>${esc(L.recommendation)}</p></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Issue / root cause</th><th>Programme / leg / run</th><th>Engineer / technician</th><th>Equipment</th><th>Impact</th><th>Lesson</th></tr></thead><tbody>${L.sources.map(x=>`<tr><td>${fmtDate(x.issue.reportedAt,true)}</td><td><strong>${esc(x.issue.issueType)}</strong><div class="small muted">${esc(x.issue.rootCause)} · ${x.issue.id}</div></td><td>${x.programme?`<span class="link" data-entity="programme" data-id="${x.programme.id}">${x.programme.id}</span>`:'—'}<div class="small muted">${x.leg?.id||'—'} · ${x.run?.id||'—'}</div></td><td>${x.staff?`<span class="link" data-entity="staff" data-id="${x.staff.id}">${esc(x.staff.name)}</span>`:'Not attributed'}</td><td>${x.equipment?`<span class="link" data-entity="equipment" data-id="${x.equipment.id}">${x.equipment.id}</span>`:'—'}</td><td>${x.issue.delayHours||0}h · ${pill(x.issue.severity)}</td><td>${esc(x.issue.lesson||x.issue.correctiveAction||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No source issues for this method.</td></tr>'}</tbody></table></div>`);wireEntities(modalBody);}
function editMethodCostModal(id){const m=state.methods.find(x=>x.id===id),c=state.settings.costFramework,o=c.methodOverrides[id]||{};if(!m)return;openModal(`<h2>${m.id} · Specific Test Cost Definition</h2><p class="small muted">Blank fields inherit skill/equipment/method defaults. These overrides apply only to ${m.id}.</p><div class="modal-grid"><div class="field"><label>Labour rate / h</label><input id="moLab" type="number" min="0" value="${o.labourRate??''}" placeholder="${c.skillRates?.[m.requiredSkills?.[0]]||c.defaultStaffRate}"></div><div class="field"><label>Equipment rate / h</label><input id="moEq" type="number" min="0" value="${o.equipmentRate??''}"></div><div class="field"><label>Fixed consumables</label><input id="moFixed" type="number" min="0" value="${o.fixedConsumables??m.fixedConsumables??0}"></div><div class="field"><label>Consumables / DUT</label><input id="moDut" type="number" min="0" value="${o.consumablesPerDut??m.consumablesPerDut??0}"></div><div class="field"><label>External / subcontract cost</label><input id="moExt" type="number" min="0" value="${o.externalCost??m.externalCost??0}"></div></div><button id="saveMethodCost" class="btn primary">Save Test-Specific Cost Model</button>`);document.getElementById('saveMethodCost').onclick=async()=>{const val=id=>document.getElementById(id).value.trim(),num=id=>val(id)===''?undefined:Number(val(id));c.methodOverrides[id]={labourRate:num('moLab'),equipmentRate:num('moEq'),fixedConsumables:num('moFixed'),consumablesPerDut:num('moDut'),externalCost:num('moExt')};for(const k of Object.keys(c.methodOverrides[id]))if(c.methodOverrides[id][k]===undefined)delete c.methodOverrides[id][k];state.audit.push(audit('Test-specific cost model changed',id,'',JSON.stringify(c.methodOverrides[id])));await persist();closeModal();render();toast(`${id} cost definition updated.`)}}
function logLegTimeModal(id){const l=state.legs.find(x=>x.id===id),m=state.methods.find(x=>x.id===l?.methodId);if(!l||!m)return;const r=state.testRuns.find(x=>x.legId===id)||{},T=methodTimeMetrics(state,m.id);openModal(`<h2>${id} · Actual Test Time</h2><p class="small muted">Component time becomes part of the method learning history and updates future planning standards automatically after sufficient evidence.</p><div class="modal-grid">${[['Setup','ltSetup',r.actualSetupHours??m.setupHours],['Execution / exposure','ltExec',r.actualExecutionHours??m.executionHours],['Teardown','ltTear',r.actualTeardownHours??m.teardownHours],['Analysis / reporting','ltAnalysis',r.actualAnalysisHours??m.analysisHours],['Queue / waiting','ltQueue',r.queueHours??0],['Rework','ltRework',r.reworkHours??0]].map(([a,k,v])=>`<div class="field"><label>${a} hours</label><input id="${k}" type="number" min="0" step="0.1" value="${v}"></div>`).join('')}</div><div class="callout"><strong>Current learned total:</strong> ${T.learned.total}h from ${T.runs} runs · productive time ${T.productivePct}%.</div><button id="saveLegTime" class="btn primary">Save Actual Time</button>`);document.getElementById('saveLegTime').onclick=async()=>{let run=state.testRuns.find(x=>x.legId===id);const vals={actualSetupHours:Number(document.getElementById('ltSetup').value)||0,actualExecutionHours:Number(document.getElementById('ltExec').value)||0,actualTeardownHours:Number(document.getElementById('ltTear').value)||0,actualAnalysisHours:Number(document.getElementById('ltAnalysis').value)||0,queueHours:Number(document.getElementById('ltQueue').value)||0,reworkHours:Number(document.getElementById('ltRework').value)||0};const total=vals.actualSetupHours+vals.actualExecutionHours+vals.actualTeardownHours+vals.actualAnalysisHours;if(run)Object.assign(run,vals,{actualHours:total});else state.testRuns.push({id:`RUN-MAN-${String(state.testRuns.length+1).padStart(3,'0')}`,legId:id,programmeId:l.programmeId,methodId:l.methodId,plannedStart:l.plannedStart,plannedEnd:l.plannedEnd,actualStart:l.actualStart||new Date().toISOString(),actualEnd:l.actualEnd||new Date().toISOString(),equipmentId:l.equipmentId,staffId:l.staffId,status:'Completed',outcome:'PASS',actualHours:total,standardHours:m.setupHours+m.executionHours+m.teardownHours+m.analysisHours,delayHours:0,source:'Manual time learning',...vals});ensureTimeLearningState(state);state.audit.push(audit('Actual test time recorded',id,'',`${total}h`));await persist();closeModal();render();toast('Actual test time saved; learned planning times refreshed.')}}
