function reportMainLegNo(l){return Math.max(1,Number(l?.validationLegNo)||Number(l?.sequence)||1)}
function reportTestLabel(l){const n=reportMainLegNo(l),sub=l?.validationSubLeg||l?.subLeg||'',step=Math.max(1,Number(l?.validationStepNo)||1);return sub?`${n}${sub}.${step}`:`${n}.${step}`}
function reportSortLegs(rows){return (rows||[]).slice().sort((a,b)=>reportMainLegNo(a)-reportMainLegNo(b)||String(a.validationSubLeg||a.subLeg||'').localeCompare(String(b.validationSubLeg||b.subLeg||''))||(Number(a.validationStepNo)||1)-(Number(b.validationStepNo)||1)||(Number(a.sequence)||0)-(Number(b.sequence)||0)||String(a.id).localeCompare(String(b.id)))}

function reportDateMs(v){const n=v?new Date(v).getTime():NaN;return Number.isFinite(n)?n:null}
function reportVisualStatus(l){const s=String(l?.status||'').toLowerCase();if(s==='completed')return'completed';if(s.includes('progress')||s==='running')return'progress';if(s==='failed'||s==='cancelled')return'failed';return'planned'}
function reportStatusLabel(l){const k=reportVisualStatus(l);return k==='completed'?'Completed':k==='progress'?'In progress':k==='failed'?'Exception':'Planned'}
function reportPlanningSwimlaneHtml(ctx){
 const legs=ctx?.legs||[];if(!legs.length)return'<div class="visual-empty">No tests in this report scope.</div>';
 const p=ctx.programme,rows=legs.map(l=>{const start=reportDateMs(l.actualStart)||reportDateMs(l.plannedStart)||reportDateMs(l.sampleReadyDate),m=state.methods.find(x=>x.id===l.methodId),hrs=m?((Number(m.setupHours)||0)+(Number(m.executionHours)||0)+(Number(m.teardownHours)||0)+(Number(m.analysisHours)||0)):8,end=reportDateMs(l.actualEnd)||reportDateMs(l.plannedEnd)||(start?start+Math.max(1,hrs)*3600000:null);return{l,start,end:end||start}}),dates=rows.flatMap(x=>[x.start,x.end]).filter(Number.isFinite);
 const due=reportDateMs(p?.dueDate),forecast=reportDateMs(p?.forecastCompletion);if(due)dates.push(due);if(forecast)dates.push(forecast);
 if(!dates.length)return'<div class="visual-empty">No dated planning records are available yet. Current status remains shown in the detail table.</div>';
 let min=Math.min(...dates),max=Math.max(...dates);if(max<=min)max=min+86400000;const pad=Math.max(43200000,(max-min)*.03);min-=pad;max+=pad;const span=max-min,pct=t=>Math.max(0,Math.min(100,(t-min)/span*100)),fmt=v=>v?fmtDate(new Date(v).toISOString()):'—';
 const dueX=due?pct(due):null,forecastX=forecast?pct(forecast):null;
 return`<div class="visual-panel"><div class="visual-head"><div><b>Portfolio execution swimlanes</b><span>Actual work transitions into forecast work on one time axis.</span></div><div class="legend"><i class="lg completed"></i>Completed<i class="lg progress"></i>In progress<i class="lg planned"></i>Planned<i class="lg failed"></i>Exception</div></div><div class="timeline-axis"><span>${fmt(min)}</span><span>${fmt(min+span/2)}</span><span>${fmt(max)}</span></div><div class="swimlanes">${dueX!=null?`<i class="milestone due" style="--x:${dueX/100}"><em>Required<br>${fmt(due)}</em></i>`:''}${forecastX!=null?`<i class="milestone forecast" style="--x:${forecastX/100}"><em>Forecast<br>${fmt(forecast)}</em></i>`:''}${rows.map(x=>{const l=x.l,s=x.start??min,e=x.end??s,w=Math.max(1.8,pct(e)-pct(s)),left=pct(s),status=reportVisualStatus(l);return`<div class="swim-row"><div class="swim-label"><b>${esc(reportTestLabel(l))}</b><span>${esc(l.name)}</span></div><div class="swim-track"><div class="swim-bar ${status}" style="left:${left}%;width:${w}%"><span>${esc(reportStatusLabel(l))}</span></div></div></div>`}).join('')}</div></div>`;
}
function reportFlowCard(l){
 const preds=(l.predecessorIds||[]).map(id=>state.legs.find(x=>x.id===id)).filter(Boolean),st=reportVisualStatus(l);
 return`<div class="flow-node ${st}"><div class="flow-node-top"><b>${esc(reportTestLabel(l))}</b><span>${esc(reportStatusLabel(l))}</span></div><strong>${esc(l.name)}</strong><small>${esc(l.methodId||'Method pending')}${preds.length?` · after ${preds.map(reportTestLabel).join(', ')}`:' · independent start'}</small></div>`;
}
function reportFlowSequence(rows){return rows.map((l,i)=>`${i?'<div class="flow-arrow">↓</div>':''}${reportFlowCard(l)}`).join('')}
function reportValidationFlowVisualHtml(ctx){
 if(!ctx||ctx.scopeType==='test')return`<div class="visual-panel"><div class="visual-head"><div><b>Selected test</b><span>Single-test report scope.</span></div></div>${ctx?.legs?.[0]?reportFlowCard(ctx.legs[0]):''}</div>`;
 const groups=[...new Set(ctx.legs.map(reportMainLegNo))].sort((a,b)=>a-b);
 return`<div class="visual-panel"><div class="visual-head"><div><b>Validation flow</b><span>Main test legs are independent. Arrows are used only inside a leg to show sequence / branch flow.</span></div><div class="legend"><i class="lg completed"></i>Completed<i class="lg progress"></i>In progress<i class="lg planned"></i>Planned</div></div><div class="flow-programme">${groups.map(n=>{const rows=reportSortLegs(ctx.legs.filter(l=>reportMainLegNo(l)===n)),branches=[...new Set(rows.map(l=>l.validationSubLeg||l.subLeg||'').filter(Boolean))],common=rows.filter(l=>!(l.validationSubLeg||l.subLeg));let body='';if(!branches.length)body=reportFlowSequence(common);else{const bSteps=rows.filter(l=>l.validationSubLeg||l.subLeg).map(l=>Number(l.validationStepNo)||1),minB=Math.min(...bSteps),maxB=Math.max(...bSteps),pre=common.filter(l=>(Number(l.validationStepNo)||1)<minB),post=common.filter(l=>(Number(l.validationStepNo)||1)>=minB);body=`${reportFlowSequence(pre)}${pre.length?'<div class="flow-arrow">↓</div>':''}<div class="branch-caption">SPLIT</div><div class="branch-grid">${branches.map(k=>`<div class="branch-col"><b>Branch ${esc(`${n}${k}`)}</b>${reportFlowSequence(rows.filter(l=>(l.validationSubLeg||l.subLeg)===k))}</div>`).join('')}</div>${post.length?`<div class="branch-caption">MERGE / CONTINUE</div>${reportFlowSequence(post)}`:''}`;}return`<div class="flow-leg"><div class="flow-leg-title">TEST LEG ${n}</div>${body||'<div class="visual-empty">No tests</div>'}</div>`}).join('')}</div></div>`;
}
function reportPolylinePoints(vals,w=620,h=150){
 if(!vals.length)return'';const sample=vals.length>240?Array.from({length:240},(_,i)=>vals[Math.round(i*(vals.length-1)/239)]):vals.slice(),min=Math.min(...sample),max=Math.max(...sample),range=max-min||1,pad=12;return sample.map((v,i)=>`${Math.round((pad+i*(w-2*pad)/Math.max(1,sample.length-1))*10)/10},${Math.round((h-pad-(v-min)/range*(h-2*pad))*10)/10}`).join(' ');
}
function reportLoggedDataGraphsHtml(sessions,legs){
 const cards=[];for(const s of sessions||[]){const l=legs.find(x=>x.id===s.legId);for(const c of s.channels||[]){const vals=(s.readings||[]).map(r=>Number(r.values?.[c.key])).filter(Number.isFinite);if(vals.length<2)continue;const min=Math.min(...vals),max=Math.max(...vals),avg=vals.reduce((a,b)=>a+b,0)/vals.length,rule=(state.liveAlertRules||[]).find(r=>r.sessionId===s.id&&r.channel===c.key),points=reportPolylinePoints(vals);cards.push(`<div class="chart-card"><div class="chart-title"><div><b>${esc(c.name||c.key)}</b><span>${esc(l?`${reportTestLabel(l)} · ${l.name}`:s.legId)} · ${vals.length} points</span></div><strong>${Math.round(avg*1000)/1000} ${esc(c.unit||'')}</strong></div><svg viewBox="0 0 620 150" role="img" aria-label="${esc(c.name||c.key)} logged data"><line x1="12" y1="20" x2="608" y2="20" class="gridline"/><line x1="12" y1="75" x2="608" y2="75" class="gridline"/><line x1="12" y1="130" x2="608" y2="130" class="gridline"/><polyline points="${points}" class="series"/></svg><div class="chart-meta"><span>Min <b>${Math.round(min*1000)/1000}</b></span><span>Avg <b>${Math.round(avg*1000)/1000}</b></span><span>Max <b>${Math.round(max*1000)/1000}</b></span>${rule&&(Number.isFinite(Number(rule.min))||Number.isFinite(Number(rule.max)))?`<span>Alert limits <b>${Number.isFinite(Number(rule.min))?rule.min:'—'}…${Number.isFinite(Number(rule.max))?rule.max:'—'}</b></span>`:''}</div></div>`);if(cards.length>=12)break;}if(cards.length>=12)break;}
 return cards.length?`<div class="chart-grid">${cards.join('')}</div>${(sessions||[]).reduce((n,s)=>n+(s.channels||[]).length,0)>cards.length?'<p class="muted">The report shows the first 12 populated channel plots; complete numeric data remains available in the logged-data appendix.</p>':''}`:'<div class="visual-empty">No populated logged-data channel is available in this report scope yet.</div>';
}
function reportScopeContext(scopeType='test',targetId='',programmeId=''){
 scopeType=['test','leg','programme'].includes(scopeType)?scopeType:'test';
 let seed=state.legs.find(x=>x.id===targetId),pid=programmeId||seed?.programmeId||state.programmes.find(x=>x.id===targetId)?.id||'';
 if(!pid&&String(targetId).startsWith('MAIN:'))pid=programmeId||state.settings.planningProject||state.programmes[0]?.id||'';
 const p=state.programmes.find(x=>x.id===pid);if(!p)return null;
 let legs=[];let mainNo=null;
 if(scopeType==='programme')legs=state.legs.filter(l=>l.programmeId===pid);
 else if(scopeType==='leg'){
   mainNo=String(targetId).startsWith('MAIN:')?Math.max(1,Number(String(targetId).split(':')[1])||1):reportMainLegNo(seed||state.legs.find(l=>l.programmeId===pid));
   legs=state.legs.filter(l=>l.programmeId===pid&&reportMainLegNo(l)===mainNo);
   seed=seed||legs[0];
 }else{
   seed=seed||state.legs.find(l=>l.programmeId===pid);if(seed)legs=[seed];
 }
 legs=reportSortLegs(legs);if(!legs.length)return null;
 const completed=legs.filter(l=>l.status==='Completed').length,failed=legs.filter(l=>l.status==='Failed'||state.results.some(r=>r.legId===l.id&&r.status==='FAIL')).length,allCompleted=completed===legs.length;
 const scopeKey=scopeType==='programme'?`programme:${pid}`:scopeType==='leg'?`leg:${pid}:${mainNo}`:`test:${legs[0].id}`;
 const title=scopeType==='programme'?`${p.id} · ${p.project}`:scopeType==='leg'?`Test Leg ${mainNo} · ${p.id}`:`${reportTestLabel(legs[0])} · ${legs[0].name}`;
 return{scopeType,targetId:scopeType==='programme'?pid:scopeType==='leg'?`MAIN:${mainNo}`:legs[0].id,scopeKey,programme:p,programmeId:pid,legs,seedLegId:legs[0]?.id,mainLegNo:mainNo,title,completed,failed,allCompleted};
}
function reportSectionSignature(keys){return REPORT_SECTION_DEFS.map(x=>x.key).filter(k=>(keys||[]).includes(k)).join('|')}
