function addCalibrationModal(preselectEq=''){const today=new Date(),due=new Date(today);due.setUTCFullYear(due.getUTCFullYear()+1);openModal(`<h2>Add Calibration Record</h2><div class="modal-grid"><div class="field"><label>Equipment</label><select id="calEq">${state.equipment.filter(e=>e.calibrationRequired).map(e=>`<option value="${e.id}" ${preselectEq===e.id?'selected':''}>${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Calibration date</label><input id="calDate" type="date" value="${today.toISOString().slice(0,10)}"></div><div class="field"><label>Due date</label><input id="calDue" type="date" value="${due.toISOString().slice(0,10)}"></div><div class="field"><label>Certificate number</label><input id="calCert" value="CERT-${Date.now().toString().slice(-6)}"></div><div class="field"><label>Provider</label><input id="calProv" value="Internal Metrology"></div><div class="field"><label>Certificate attachment</label><input id="calFile" type="file" accept="application/pdf,image/*"></div></div><div class="callout warning"><strong>Completion evidence</strong><p>This form records a completed calibration result. A scheduled calibration is not converted to Pass until this evidence-backed record is saved.</p></div><button id="saveCal" class="btn primary">Save completed calibration</button>`);document.getElementById('saveCal').onclick=async()=>{const eqId=document.getElementById('calEq').value,date=document.getElementById('calDate').value,dueDate=document.getElementById('calDue').value,cert=document.getElementById('calCert').value.trim();if(!date||!dueDate||new Date(dueDate)<=new Date(date))return toast('Due date must be after calibration date.');if(!cert)return toast('Certificate / calibration record number is required.');const file=document.getElementById('calFile').files[0];let attachmentData=null;if(file)attachmentData=await fileToDataURL(file);const c={id:`CAL-${String(state.calibrations.length+1).padStart(3,'0')}`,equipmentId:eqId,calibrationDate:new Date(date+'T09:00:00Z').toISOString(),dueDate:new Date(dueDate+'T17:00:00Z').toISOString(),certificateNumber:cert,provider:document.getElementById('calProv').value,result:'Pass',comments:'User-added completed calibration',certificatePath:attachmentData||'',uncertainty:'See calibration record',asFound:'Within tolerance',asLeft:'Within tolerance',measurementTable:[]};state.calibrations.push(c);const eq=state.equipment.find(e=>e.id===eqId);if(eq){eq.calibrationDue=c.dueDate;eq.currentCalibrationId=c.id;}for(const a of decisionIntelligenceStore().actions)refreshGovernedAction(state,a);state.settings.planDirty=true;state.audit.push(audit('Completed calibration added',eqId,'',c.id));planningAdvisorCache=null;decisionIntelligenceCache=null;await persist();closeModal();render();toast('Completed calibration record saved. Any linked implementation action has been re-evaluated.');}}
function fileToDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}

function search(q){q=q.trim().toLowerCase();if(q.length<2){searchOverlay.classList.add('hidden');return}const hits=[];const add=(type,id,label,sub)=>hits.push({type,id,label,sub});for(const r of state.requirements)if(`${r.id} ${r.sourceId} ${r.text}`.toLowerCase().includes(q))add('requirement',r.id,r.id,r.text);for(const p of state.programmes)if(`${p.id} ${p.project} ${p.product} ${p.customer}`.toLowerCase().includes(q))add('programme',p.id,`${p.id} · ${p.project}`,p.product);for(const d of state.duts)if(`${d.id} ${d.serialNumber}`.toLowerCase().includes(q))add('dut',d.id,d.id,d.serialNumber);for(const e of state.equipment)if(`${e.id} ${e.assetNumber} ${e.serialNumber} ${e.name}`.toLowerCase().includes(q))add('equipment',e.id,`${e.id} · ${e.name}`,`${e.assetNumber} · ${e.serialNumber}`);for(const m of state.methods)if(`${m.id} ${m.name}`.toLowerCase().includes(q))add('method',m.id,`${m.id} · ${m.name}`,m.category);for(const sp of state.specifications||[])if(`${sp.id} ${sp.name} ${sp.revision} ${sp.owner} ${sp.documentName}`.toLowerCase().includes(q))add('specification',sp.id,`${sp.id} Rev ${sp.revision}`,`${sp.programmeId} · ${sp.name}`);for(const i of state.issues||[])if(`${i.id} ${i.issueType} ${i.rootCause} ${i.description}`.toLowerCase().includes(q))add('programme',i.programmeId,`${i.id} · ${i.issueType}`,`${i.rootCause} · ${i.programmeId}`);for(const o of state.opportunities||[])if(`${o.id} ${o.name} ${o.customer} ${o.product}`.toLowerCase().includes(q))add('programme',o.similarProgrammeId||state.programmes[0]?.id,`${o.id} · ${o.name}`,`Potential project · ${o.probability}% probability`);for(const a of state.audits||[])if(`${a.id} ${a.name} ${AUDIT_STANDARDS[a.standard]?.name}`.toLowerCase().includes(q))add('programme',state.programmes[0]?.id,`${a.id} · ${a.name}`,AUDIT_STANDARDS[a.standard]?.name||a.standard);for(const r of state.prototypeRequests||[])if(`${r.id} ${r.name} ${r.project} ${r.product} ${r.linkedProgrammeId}`.toLowerCase().includes(q))add('prototype',r.id,`${r.id} · ${r.name}`,`${r.project} · ${r.quantity} ${r.buildType} units · ${r.status}`);for(const s of state.staff)if(`${s.id} ${s.name} ${s.role}`.toLowerCase().includes(q))add('staff',s.id,`${s.name} · ${s.id}`,s.role);for(const c of state.calibrations)if(`${c.id} ${c.certificateNumber}`.toLowerCase().includes(q))add('equipment',c.equipmentId,`${c.certificateNumber}`,`${c.id} · ${c.equipmentId}`);searchOverlay.innerHTML=hits.slice(0,16).map(h=>`<div class="search-hit" data-entity="${h.type}" data-id="${h.id}"><small>${h.type}</small><strong>${esc(h.label)}</strong><div class="small muted">${esc(h.sub).slice(0,100)}</div></div>`).join('')||'<div class="empty">No matches.</div>';searchOverlay.classList.remove('hidden');wireEntities(searchOverlay);for(const x of searchOverlay.querySelectorAll('[data-entity]'))x.addEventListener('click',()=>searchOverlay.classList.add('hidden'))}

function download(name,content,type='application/octet-stream'){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportJSON(){download(`LabOS-${APP_VERSION}-data.json`,JSON.stringify(state,null,2),'application/json');state.audit.push(audit('Data exported','System','','JSON'));persist();toast('Full system data exported to JSON.');}
async function importJSON(e){const f=e.target.files[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(!obj.meta||!Array.isArray(obj.programmes)||!Array.isArray(obj.legs))throw new Error('Not a LabOS data export');state=ensureStateShape(obj);state.meta.version=APP_VERSION;addCompletedBookings(state);recomputeRequirementStatuses(state);state.audit=state.audit||[];state.audit.push(audit('Data imported','System',f.name,'Loaded'));await persist();render();toast('JSON data imported successfully.');}catch(err){toast(`Import rejected: ${err.message}`)}e.target.value=''}
async function resetDemo(){if(!confirm('Reset all browser-local changes and restore the deterministic demo dataset?'))return;await clearState();state=ensureStateShape(createDemoData());addCompletedBookings(state);schedulePrototypeBuilds(state);const r=scheduleAll(state,{recordAudit:false});state=r.data;lastPlanDiagnostics=r.diagnostics;recomputeRequirementStatuses(state);await persist();render();toast('Deterministic demo data restored.');}
function exportCSV(kind,id=null){
 let rows=[];
 if(kind==='requirements')rows=state.requirements.map(r=>({id:r.id,source:r.sourceId,programme:r.programmeId,criticality:r.criticality,status:r.status,text:r.text,testLegs:r.testLegIds?.join('|')||''}));
 else if(kind==='equipment')rows=state.equipment.map(e=>({id:e.id,asset:e.assetNumber,name:e.name,type:e.type,status:e.status,location:e.location,calibrationDue:e.calibrationDue,chargeRatePerHour:e.chargeRatePerHour}));
 else if(kind==='plan')rows=state.bookings.map(b=>({booking:b.id,programme:b.programmeId,leg:b.legId,method:b.methodId,start:b.start,end:b.end,equipment:b.equipmentId,staff:b.staffId,priority:b.priority,lateHours:b.lateHours,locked:b.locked}));
 else if(kind==='kpis'){const x=kpis(state);rows=Object.entries(x).map(([metric,value])=>({metric,value}));}
 else if(kind==='costs')rows=portfolioCost(state).programmes.flatMap(pc=>pc.legs.map(x=>({programme:pc.programmeId,project:state.programmes.find(p=>p.id===pc.programmeId)?.project,leg:x.leg.id,method:x.leg.methodId,status:x.leg.status,labour:x.estimate.labour,equipment:x.estimate.equipment,consumables:x.estimate.consumables,external:x.estimate.external,development:x.estimate.development,overhead:x.estimate.overhead,contingency:x.estimate.contingency,total:x.estimate.total,programmeBudget:pc.budget,programmeForecast:pc.forecast,programmeVariance:pc.variance})));
 else if(kind==='capacity'){
  const cf=capacityForecast(state,Number(state.settings.capacityHorizon)||12,state.settings.pipelineMode||'weighted');
  const eq=cf.weeks.flatMap(w=>w.equipment.filter(x=>x.total>0).map(x=>({week:w.start.slice(0,10),resourceType:'Equipment',resource:x.type,confirmedHours:Math.round(x.confirmed),pipelineHours:Math.round(x.pipeline),capacityHours:Math.round(x.capacity),gapHours:Math.round(x.gapHours),need:x.unitsGap})));
  const staff=cf.weeks.flatMap(w=>w.staff.filter(x=>x.total>0).map(x=>({week:w.start.slice(0,10),resourceType:'Staff skill',resource:x.skill,confirmedHours:Math.round(x.confirmed),pipelineHours:Math.round(x.pipeline),capacityHours:Math.round(x.capacity),gapHours:Math.round(x.gapHours),need:x.fteGap})));
  rows=eq.concat(staff);
 }
 else if(kind==='maintenance')rows=state.maintenancePolicies.map(p=>{const eq=state.equipment.find(e=>e.id===p.equipmentId),ev=state.maintenance.find(m=>m.policyId===p.id);return{policy:p.id,equipment:p.equipmentId,name:eq?.name,type:eq?.type,criticality:p.criticality,strategy:p.strategy,conditionScore:p.conditionScore,failureRisk:p.failureRisk,nextDue:p.nextDueDate,durationHours:p.durationHours,plannedStart:ev?.start||'',plannedEnd:ev?.end||''}});
 else if(kind==='audit'){const a=state.audits.find(x=>x.id===id)||state.audits.at(-1);rows=a.items.map(i=>({audit:a.id,standard:AUDIT_STANDARDS[a.standard]?.name,reference:i.reference,section:i.section,title:i.title,status:i.status,evidence:i.evidence,finding:i.finding,owner:i.owner,dueDate:i.dueDate||''}));}
 else rows=state.calibrations.map(c=>({id:c.id,equipment:c.equipmentId,date:c.calibrationDate,due:c.dueDate,certificate:c.certificateNumber,provider:c.provider,result:c.result}));
 const cols=Object.keys(rows[0]||{}),csv=[cols.join(','),...rows.map(r=>cols.map(c=>`"${String(r[c]??'').replaceAll('"','""')}"`).join(','))].join('\n');download(`LabOS-${kind}.csv`,csv,'text/csv');toast(`${kind} CSV exported.`)
}
function verifyUI(){const d=runDiagnostics(state);openModal(`<h2>System Verification · ${d.overall}</h2><div class="callout ${d.overall==='PASS'?'':'danger'}"><strong>${d.pass}/${d.checks.length} checks passed</strong></div><div class="list">${d.checks.map(c=>`<div class="checkline"><span class="${c.ok?'diag-pass':'diag-fail'}">${c.ok?'PASS':'FAIL'}</span><strong>${esc(c.name)}</strong><span class="small muted">${esc(c.detail)}</span></div>`).join('')}</div>`)}



function advanceQualityEvent(id){const q=state.qualityEvents.find(x=>x.id===id);if(!q)return;const stages=['Containment','Investigation','Root Cause','Disposition','CAPA','CAPA Verification','Closed'],i=Math.max(0,stages.indexOf(q.status)),next=stages[Math.min(stages.length-1,i+1)];if(next===q.status)return toast(`${id} is already closed.`);const extra=next==='Root Cause'?`<div class="field"><label>Confirmed root cause</label><textarea id="qeDecision" placeholder="Evidence-supported root cause"></textarea></div>`:next==='Disposition'?`<div class="field"><label>MRB / disposition decision</label><textarea id="qeDecision" placeholder="Use-as-is / rework / retest / scrap / return, with justification"></textarea></div>`:next==='Closed'?`<div class="callout warning"><strong>Closure gate</strong><p>All CAPA actions must be effectiveness-verified before this event can close.</p></div>`:'';openModal(`<h2>${q.id} · Advance to ${next}</h2><div class="callout"><strong>${esc(q.type)} · current stage ${q.status}</strong><p>Stage advancement requires objective evidence; LabOS will not auto-generate a root cause, disposition or effectiveness conclusion.</p></div>${extra}<div class="field"><label>Evidence / investigation record</label><textarea id="qeEvidence" placeholder="Report, data review, photo, measurement record, meeting decision, retest evidence..."></textarea></div><div class="field"><label>Evidence reviewed by</label><select id="qeReviewer">${state.staff.map(s=>`<option value="${s.name}">${esc(s.name)} · ${esc(s.role)}</option>`).join('')}</select></div><button id="confirmQEAdvance" class="btn primary">Record Evidence & Advance</button>`);document.getElementById('confirmQEAdvance').onclick=async()=>{const evidence=document.getElementById('qeEvidence').value.trim(),decision=document.getElementById('qeDecision')?.value.trim()||'',reviewer=document.getElementById('qeReviewer').value;if(!evidence)return toast('Objective evidence is required before stage advancement.');if(['Root Cause','Disposition'].includes(next)&&!decision)return toast(`${next} decision is required.`);if(next==='Closed'){const capas=state.capaActions.filter(c=>c.qualityEventId===id);if(capas.length&&capas.some(c=>c.effectivenessStatus!=='Effective'))return toast('Closure rejected: all CAPA actions must have effectiveness evidence.');}q.evidenceRefs=[...(q.evidenceRefs||[]),{stage:next,evidence,reviewedBy:reviewer,timestamp:new Date().toISOString()}];if(next==='Root Cause')q.rootCause=decision;if(next==='Disposition')q.disposition=decision;if(next==='Closed'){q.closedAt=new Date().toISOString();q.effectivenessStatus='Effective';}const prev=q.status;q.status=next;state.audit.push(audit('Quality event evidence-backed stage change',id,prev,`${next} · ${evidence}`));state.settings.planDirty=true;await persist();closeModal();render();toast(`${id} advanced to ${next} with evidence.`)}}

function custodyBatchModal(){const pid=state.settings.custodyProgramme||state.programmes[0]?.id,duts=state.duts.filter(d=>!pid||d.programmeId===pid).slice(0,20);openModal(`<h2>Batch Custody Move</h2><p class="small muted">Select DUTs and record one controlled movement/disposition event.</p><div class="check-grid">${duts.map(d=>`<label class="review-check"><input class="cbDut" type="checkbox" value="${d.id}"><span><strong>${d.id}</strong><small>${d.serialNumber} · ${currentCustody(state,d.id).status}</small></span></label>`).join('')}</div><label>Destination<select id="cbTo">${state.sampleLocations.map(l=>`<option value="${l.id}">${l.id} · ${esc(l.name)}</option>`).join('')}</select></label><label>Event<select id="cbType"><option>Moved</option><option>Released</option><option>Quarantined</option><option>Issued to Test</option><option>Returned</option><option>Retained</option><option>Disposed</option></select></label><button id="saveBatchCustody" class="btn primary">Record Batch Move</button>`);document.getElementById('saveBatchCustody').onclick=async()=>{const ids=[...modalBody.querySelectorAll('.cbDut:checked')].map(x=>x.value);if(!ids.length)return toast('Select at least one DUT.');for(const id of ids)moveDut(state,id,document.getElementById('cbTo').value,document.getElementById('cbType').value,state.settings.actor,'Batch controlled movement');state.audit.push(audit('Batch DUT custody changed',pid,'',`${ids.length} DUTs`));state.settings.planDirty=true;await persist();closeModal();render();toast(`${ids.length} DUTs moved.`)};}
function guidedStartSelectModal(){const legs=state.legs.filter(l=>!['Completed','Cancelled','Failed'].includes(l.status)&&templateForMethod(state,l.methodId));openModal(`<h2>Start Guided Test</h2><div class="list">${legs.slice(0,30).map(l=>{const R=executionReadiness(state,l);return`<div class="list-row"><div><strong>${l.id} · ${esc(l.name)}</strong><small>${l.programmeId} · ${l.methodId}${R.reasons.length?` · ${esc(R.reasons[0])}`:''}</small></div><div class="actions">${pill(R.ok?'Ready':'Blocked')}<button class="btn small primary" data-act="guided-start" data-id="${l.id}" ${R.ok?'':'disabled'}>Start</button></div></div>`}).join('')}</div>`);wireModalActions();}
async function startGuidedForLeg(id){const l=state.legs.find(x=>x.id===id);if(!l)return;const R=executionReadiness(state,l);if(!R.ok)return toast(`Cannot start: ${R.reasons.join(' ')}`);const ex=startGuidedExecution(state,id,l.staffId||state.staff[0]?.id);if(!ex)return toast('No released guided execution template exists for this method.');for(const dutId of l.dutIds||[])moveDut(state,dutId,'LOC-TEST','Issued to Test',state.settings.actor,`Issued to ${l.id}`);state.audit.push(audit('Guided execution started',ex.id,'',id));await persist();closeModal();guidedOpenModal(ex.id);}
function newUncertaintyModal(){openModal(`<h2>New Measurement Uncertainty Budget</h2><div class="modal-grid"><div class="field"><label>Method</label><select id="ubMethod">${state.methods.filter(m=>m.active).map(m=>`<option value="${m.id}">${m.id} · ${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label>Equipment</label><select id="ubEq">${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Measurand</label><input id="ubMeas" value="Measured response"></div><div class="field"><label>Unit</label><input id="ubUnit" value="% of reading"></div><div class="field"><label>Expanded uncertainty</label><input id="ubVal" type="number" step="0.01" value="0.8"></div></div><button id="saveUB" class="btn primary">Release Budget</button>`);document.getElementById('saveUB').onclick=async()=>{const x={id:`UNC-${String(state.uncertaintyBudgets.length+1).padStart(3,'0')}`,methodId:document.getElementById('ubMethod').value,equipmentId:document.getElementById('ubEq').value,measurand:document.getElementById('ubMeas').value,unit:document.getElementById('ubUnit').value,components:[{source:'Reference standard',type:'B',stdUncertainty:0.2},{source:'Repeatability',type:'A',stdUncertainty:0.25}],combinedUncertainty:Math.round(Number(document.getElementById('ubVal').value)/2*100)/100,k:2,expandedUncertainty:Number(document.getElementById('ubVal').value),status:'Released',reviewDue:dayISO(180)};state.uncertaintyBudgets.push(x);state.audit.push(audit('Uncertainty budget released',x.id,'',x.methodId));await persist();closeModal();render();toast(`${x.id} released.`)};}
function newInventoryModal(){openModal(`<h2>New Fixture / Consumable / Spare</h2><div class="modal-grid"><div class="field"><label>ID</label><input id="niId" value="ITEM-${String(state.inventoryItems.length+1).padStart(3,'0')}"></div><div class="field"><label>Name</label><input id="niName" value="New laboratory item"></div><div class="field"><label>Type</label><select id="niType"><option>Fixture</option><option>Consumable</option><option>Spare</option></select></div><div class="field"><label>On hand</label><input id="niOn" type="number" min="0" value="1"></div><div class="field"><label>Reorder point</label><input id="niRe" type="number" min="0" value="1"></div><div class="field"><label>Lead time days</label><input id="niLead" type="number" min="0" value="14"></div></div><label>Compatible method IDs (comma separated)<input id="niMethods" value=""></label><button id="saveNI" class="btn primary">Add Item</button>`);document.getElementById('saveNI').onclick=async()=>{const x={id:document.getElementById('niId').value.trim(),name:document.getElementById('niName').value.trim(),type:document.getElementById('niType').value,onHand:Number(document.getElementById('niOn').value),reorderPoint:Number(document.getElementById('niRe').value),leadTimeDays:Number(document.getElementById('niLead').value),unitCost:0,compatibleMethodIds:document.getElementById('niMethods').value.split(',').map(x=>x.trim()).filter(Boolean),location:'Stores',status:'Available',criticality:'Normal',lastCount:new Date().toISOString()};if(!x.id||state.inventoryItems.some(i=>i.id===x.id))return toast('Use a unique item ID.');state.inventoryItems.push(x);state.audit.push(audit('Inventory item added',x.id,'',x.type));await persist();closeModal();render();toast(`${x.id} added.`)};}
function materialLegModal(id){const l=state.legs.find(x=>x.id===id),R=l&&inventoryReadiness(state,l);if(!l)return;openModal(`<h2>${l.id} · Fixture / Material Readiness</h2><div class="callout ${R.ok?'':'warning'}"><strong>${R.ok?'Ready':'Blocked'}</strong><div>${esc(R.reason||'All required fixtures and consumables available.')}</div></div><div class="list">${R.bad.map(x=>`<div class="list-row"><div><strong>${x.item.id} · ${esc(x.item.name)}</strong><small>need ${x.needed} · available ${x.available} · lead time ${x.item.leadTimeDays}d</small></div><button class="btn small" data-act="inventory-adjust" data-id="${x.item.id}">Adjust / reorder</button></div>`).join('')||'<div class="empty">No shortages.</div>'}</div>`);wireModalActions();}
function newExternalLabModal(){openModal(`<h2>Add External Laboratory</h2><div class="modal-grid"><div class="field"><label>Name</label><input id="elName" value="New Approved Test Partner"></div><div class="field"><label>Categories (comma separated)</label><input id="elCats" value="Environmental, Reliability"></div><div class="field"><label>Turnaround days</label><input id="elDays" type="number" value="10"></div><div class="field"><label>Base cost</label><input id="elCost" type="number" value="3000"></div></div><label>Accreditation scope<input id="elAcc" value="ISO/IEC 17025 scope to be verified"></label><button id="saveEL" class="btn primary">Add as Conditional Supplier</button>`);document.getElementById('saveEL').onclick=async()=>{const x={id:`EXT-${String(state.externalLabs.length+1).padStart(3,'0')}`,name:document.getElementById('elName').value,categories:document.getElementById('elCats').value.split(',').map(x=>x.trim()).filter(Boolean),accreditation:document.getElementById('elAcc').value,turnaroundDays:Number(document.getElementById('elDays').value),expediteDays:Math.max(2,Math.round(Number(document.getElementById('elDays').value)/2)),baseCost:Number(document.getElementById('elCost').value),qualityScore:80,onTimePct:80,capacityPerWeek:2,status:'Conditional',location:'TBD'};state.externalLabs.push(x);state.audit.push(audit('External laboratory added',x.id,'',x.name));await persist();closeModal();render();toast(`${x.id} added as Conditional pending approval.`)};}
async function commitExternal(legId,labId){const job=outsourceLeg(state,legId,labId);if(!job)return toast('Unable to outsource this leg.');state.audit.push(audit('Test leg outsourced',legId,'Internal',`${labId} · ${job.id}`));state.settings.planDirty=true;await persist();closeModal();render();toast(`${legId} outsourced to ${labId}; internal booking removed.`)}
function exportInventoryCSV(){const rows=state.inventoryItems.map(i=>({id:i.id,name:i.name,type:i.type,onHand:i.onHand,reorderPoint:i.reorderPoint,leadTimeDays:i.leadTimeDays,unitCost:i.unitCost,methods:(i.compatibleMethodIds||[]).join('|'),location:i.location,status:i.status})),cols=Object.keys(rows[0]||{}),csv=[cols.join(','),...rows.map(r=>cols.map(c=>`"${String(r[c]??'').replaceAll('"','""')}"`).join(','))].join('\n');download('LabOS-inventory.csv',csv,'text/csv');toast('Inventory CSV exported.');}

// v0.8.0 P1/P2 operational layers -------------------------------------------------
function renderQuality(){ensureAdvancedState(state);const Q=qualitySummary(state),rows=state.qualityEvents.slice().sort((a,b)=>new Date(b.detectedAt)-new Date(a.detectedAt)),uncaptured=state.issues.filter(i=>!state.qualityEvents.some(q=>q.sourceType==='Issue'&&q.sourceId===i.id)).slice(0,8);return pageHead('Quality Events / NCR / OOS / CAPA','Unified deviation-to-CAPA workflow: containment → investigation → root cause → disposition → corrective/preventive action → effectiveness verification',`<button class="btn" data-act="quality-from-issues">Capture Recent Issues</button><button class="btn primary" data-act="new-quality">＋ Quality Event</button>`)+`<div class="grid kpi visual-kpis">${kpiCard('Open quality events',Q.open,'Deviation / NCR / OOS / OOT')}${kpiCard('Major / critical',Q.major,'Require containment and management visibility')}${kpiCard('Overdue actions',Q.overdue,'Open events past target date')}${kpiCard('Open CAPA',Q.capaOpen,'Corrective / preventive actions')}${kpiCard('CAPA effectiveness',`${Q.effectivenessPct}%`,'Verified effective actions')}${kpiCard('Closed events',Q.closed,'Evidence retained in audit history')}</div><div class="grid section-grid equal">${section('Quality event workbench',`<div class="table-wrap"><table><thead><tr><th>Event</th><th>Type / severity</th><th>Programme / leg</th><th>Stage</th><th>Owner / due</th><th>Root cause</th><th>Action</th></tr></thead><tbody>${rows.map(q=>`<tr><td><strong>${q.id}</strong><div class="small muted">${fmtDate(q.detectedAt,true)} · source ${q.sourceType} ${q.sourceId||''}</div></td><td>${pill(q.type)} ${pill(q.severity)}</td><td>${q.programmeId||'—'}<div class="small muted">${q.legId||'programme-level'} · ${(q.dutIds||[]).length} DUT(s)</div></td><td>${pill(q.status)}</td><td>${esc(q.owner)}<div class="small muted">due ${fmtDate(q.dueDate)}</div></td><td>${esc(q.rootCause||'Under investigation')}</td><td><button class="btn small primary" data-act="quality-detail" data-id="${q.id}">Open investigation</button></td></tr>`).join('')}</tbody></table></div>`,'Quality events connect directly to test evidence, DUTs, issues and CAPA')}${section('Issue → quality-event intake',`<div class="list">${uncaptured.map(i=>`<div class="list-row"><div><strong>${i.id} · ${esc(i.issueType)}</strong><small>${i.programmeId} · ${i.legId||'programme'} · ${i.severity} · ${i.delayHours||0}h impact</small></div><button class="btn small" data-act="quality-capture-issue" data-id="${i.id}">Create Quality Event</button></div>`).join('')||'<div class="empty">All recent issues are already represented in the quality-event workflow.</div>'}</div>`,'Live anomalies and manual issues can be promoted into the same governed workflow')}</div><div style="margin-top:14px">${section('CAPA action register',`<div class="table-wrap"><table><thead><tr><th>CAPA</th><th>Quality event</th><th>Action</th><th>Owner</th><th>Due</th><th>Status</th><th>Effectiveness</th></tr></thead><tbody>${state.capaActions.map(c=>`<tr><td>${c.id}</td><td><button class="link-button" data-act="quality-detail" data-id="${c.qualityEventId}">${c.qualityEventId}</button></td><td>${esc(c.description)}</td><td>${esc(c.owner)}</td><td>${fmtDate(c.dueDate)}</td><td>${pill(c.status)}</td><td>${pill(c.effectivenessStatus)}</td></tr>`).join('')}</tbody></table></div>`,'Effectiveness verification closes the feedback loop and remains traceable to the originating event')}</div>`;}

function renderCustody(){ensureAdvancedState(state);const pid=state.settings.custodyProgramme||'',C=custodySummary(state,pid),G=sampleGroupSummary(state,pid);return pageHead('Samples, DUTs & Chain of Custody','Receipt, identity, location, quarantine, split/merge populations, issue-to-test, retention and disposal are controlled readiness inputs',`<button class="btn" data-act="custody-scan">⌁ Simulate QR Scan</button><button class="btn" data-act="custody-merge-groups">Merge Groups</button><button class="btn primary" data-act="custody-move-batch">⇄ Move / Release DUTs</button>`)+`<div class="project-plan-bar card"><label>Programme<select id="custodyProgramme"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select></label><div class="project-plan-meta"><strong>Chain-of-custody readiness</strong><span>Quarantine/disposal and population genealogy feed directly into execution and scheduling readiness.</span></div></div><div class="grid kpi visual-kpis">${kpiCard('DUTs in scope',C.total,'Serialized validation population')}${kpiCard('Released / available',C.available,'Ready for planned test use')}${kpiCard('Quarantine',C.quarantine,'Requires disposition before execution')}${kpiCard('Active populations',G.active,'Split / merge genealogy')}${kpiCard('In test',C.inTest,'Current execution location')}${kpiCard('Custody events',state.custodyEvents.length,'Movement / disposition history')}</div><div class="grid section-grid equal">${section('DUT location & readiness',`<div class="table-wrap"><table><thead><tr><th>DUT</th><th>Programme</th><th>Status</th><th>Current location</th><th>Last event</th><th>Action</th></tr></thead><tbody>${C.rows.slice(0,120).map(r=>`<tr><td><span class="link mono" data-entity="dut" data-id="${r.dut.id}">${r.dut.id}</span><div class="small muted">${r.dut.serialNumber}</div></td><td>${r.dut.programmeId}</td><td>${pill(r.status)}</td><td>${esc(state.sampleLocations.find(l=>l.id===r.location)?.name||r.location)}</td><td>${r.lastEvent?`${esc(r.lastEvent.type)} · ${fmtDate(r.lastEvent.timestamp,true)}<div class="small muted">${esc(r.lastEvent.actor)}</div>`:'—'}</td><td><button class="btn small" data-act="custody-detail" data-id="${r.dut.id}">History</button><button class="btn small primary" data-act="custody-move" data-id="${r.dut.id}">Move</button></td></tr>`).join('')}</tbody></table></div>`,'DUT state is an execution/planning gate, not an informational label')}${section('Validation populations / genealogy',`<div class="list">${G.groups.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).map(g=>`<div class="list-row"><div><strong>${g.id} · ${esc(g.name)}</strong><small>${g.programmeId} · ${(g.memberIds||[]).length} DUTs · parents ${(g.parentGroupIds||[]).join(', ')||'original population'} · ${g.status}</small></div><div class="actions">${pill(g.status)}${g.status==='Active'&&(g.memberIds||[]).length>1?`<button class="btn small" data-act="custody-split-group" data-id="${g.id}">Split</button>`:''}</div></div>`).join('')||'<div class="empty">No sample groups in scope.</div>'}</div>`,'Splits and joins preserve population lineage while individual DUT custody remains authoritative')}</div><div style="margin-top:14px">${section('Storage / process locations',`<div class="grid mini-grid">${state.sampleLocations.map(l=>{const n=C.rows.filter(r=>r.location===l.id).length;return`<div class="mini-card"><strong>${l.id} · ${esc(l.name)}</strong><small>${esc(l.type)} · ${esc(l.condition)}</small><b>${n}</b></div>`}).join('')}</div>`,'Locations can map to QR/barcode scanners and controlled storage conditions in production')}</div>`;}
function renderGuided(){ensureAdvancedState(state);const openLegs=state.legs.filter(l=>!['Completed','Cancelled','Failed'].includes(l.status)&&templateForMethod(state,l.methodId)).slice(0,40),active=state.guidedExecutions.filter(x=>x.status==='In Progress'),review=state.guidedExecutions.filter(x=>x.status==='Awaiting Review'),completed=state.guidedExecutions.filter(x=>x.status==='Completed');return pageHead('Guided Laboratory Execution (LES)','Controlled step-by-step execution with mandatory checks, evidence, review-by-exception and quality-event routing',`<button class="btn" data-route-jump="live">◉ Live Monitor</button><button class="btn primary" data-act="guided-start-select">▶ Start Guided Test</button>`)+`<div class="grid kpi visual-kpis">${kpiCard('Released work instructions',state.lesTemplates.filter(x=>x.status==='Released').length,'Versioned LES templates')}${kpiCard('Active executions',active.length,'Step-controlled test work')}${kpiCard('Awaiting review',review.length,'Review-by-exception queue')}${kpiCard('Completed executions',completed.length,'Approved execution records')}${kpiCard('Execution exceptions',state.guidedExecutions.reduce((a,x)=>a+x.stepStates.filter(s=>s.exception).length,0),'Route automatically to quality')}${kpiCard('Ready candidate legs',openLegs.filter(l=>executionReadiness(state,l).ok).length,'All operational gates green')}</div><div class="grid section-grid equal">${section('Active / review executions',`<div class="list">${[...active,...review].map(ex=>{const l=state.legs.find(x=>x.id===ex.legId),done=ex.stepStates.filter(s=>s.status==='Completed').length,R=ex.status==='Awaiting Review'?guidedReviewReadiness(state,ex.id):null;return`<div class="list-row"><div><strong>${ex.id} · ${l?.id||ex.legId} · ${esc(l?.name||'')}</strong><small>${done}/${ex.stepStates.length} steps · ${ex.status} · operator ${state.staff.find(s=>s.id===ex.operatorId)?.name||ex.operatorId}${R&&!R.ok?` · ${esc(R.reasons[0])}`:''}</small></div><button class="btn small primary" data-act="guided-open" data-id="${ex.id}">${ex.status==='Awaiting Review'?'Review':'Open execution'}</button></div>`}).join('')||'<div class="empty">No active guided executions.</div>'}</div>`,'A test cannot be approved while mandatory steps or execution deviations remain open')}${section('Execution-ready work queue',`<div class="list">${openLegs.slice(0,15).map(l=>{const R=executionReadiness(state,l);return`<div class="list-row"><div><strong>${l.id} · ${esc(l.name)}</strong><small>${l.programmeId} · ${l.methodId} · ${(l.dutIds||[]).length} DUTs${R.reasons.length?` · ${esc(R.reasons[0])}`:''}</small></div><div class="actions">${pill(R.ok?'Ready':'Blocked')}${R.ok?`<button class="btn small primary" data-act="guided-start" data-id="${l.id}">Start</button>`:`<button class="btn small primary" data-act="guided-blocker" data-id="${l.id}">Resolve blocker →</button>`}</div></div>`}).join('')}</div>`,'Readiness combines programme release, method, custody, inventory, quality, calibration and metrology controls')}</div>`;}
function renderTwin(){ensureAdvancedState(state);const pid=state.settings.twinProgramme||'',iterations=state.settings.digitalTwin?.iterations||400,T=digitalTwinForecast(state,{iterations,programmeId:pid}),rows=T.results;return pageHead('Planning Digital Twin','Monte-Carlo-style delivery confidence built from actual method-duration variance, issue/rework/failure history and the current resource plan',`<button class="btn" data-act="twin-settings">⚙ Simulation</button><button class="btn primary" data-act="twin-run">↻ Recalculate Twin</button>`)+`<div class="project-plan-bar card"><label>Scope<select id="twinProgramme"><option value="">Portfolio</option>${state.programmes.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select></label><div class="project-plan-meta"><strong>${iterations} deterministic seeded iterations</strong><span>P50 = expected; P80 = planning confidence; P95 = stress case. This is decision support, not a guarantee.</span></div></div><div class="grid kpi visual-kpis">${kpiCard('Portfolio on-time confidence',`${T.portfolioOnTime}%`,'Average simulated programme probability')}${kpiCard('Programmes <80%',T.atRisk,'Planning attention threshold')}${kpiCard('Programmes <60%',T.critical,'High delivery risk')}${kpiCard('Simulation runs',T.iterations,'Per programme')}${kpiCard('Current deterministic plan',state.programmes.filter(p=>p.scheduleRisk==='On Track').length,'Programmes on-track today')}${kpiCard('Risk-adjusted view','P50 / P80 / P95','Use P80 for commitment conversations')}</div><div style="margin-top:14px">${section('Programme delivery confidence',`<div class="table-wrap"><table><thead><tr><th>Programme</th><th>Due date</th><th>On-time probability</th><th>P50</th><th>P80</th><th>P95</th><th>Risk</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="link mono" data-entity="programme" data-id="${r.programmeId}">${r.programmeId}</span><div class="small muted">${esc(r.project)}</div></td><td>${fmtDate(r.dueDate)}</td><td><strong>${r.onTimePct}%</strong><div class="progress"><span style="width:${r.onTimePct}%"></span></div></td><td>${fmtDate(r.p50)}</td><td><strong>${fmtDate(r.p80)}</strong></td><td>${fmtDate(r.p95)}</td><td>${pill(r.risk)}</td></tr>`).join('')}</tbody></table></div>`,'Future enhancement for production: correlated resource failures and full discrete-event simulation')}</div>`;}

function renderMetrology(){ensureAdvancedState(state);const M=metrologySummary(state),msa=[...state.msaStudies].sort((a,b)=>new Date(b.date)-new Date(a.date)),ootEq=[...new Set(state.calibrations.filter(c=>c.result!=='Scheduled'&&c.asFound&&!/within tolerance|within spec|acceptable/i.test(c.asFound)).map(c=>c.equipmentId))];return pageHead('Metrology, MSA & Measurement Uncertainty','Measurement capability, Gage R&R, uncertainty budgets, reference standards and retrospective impact analysis',`<button class="btn" data-act="new-uncertainty">＋ Uncertainty Budget</button><button class="btn primary" data-act="new-msa">＋ MSA / Gage R&R</button>`)+`<div class="grid kpi visual-kpis">${kpiCard('MSA studies',M.msa,`${M.badMsa} unacceptable · ${M.conditional} conditional`)}${kpiCard('Uncertainty budgets',M.uncertainty,`${M.uncertaintyDue} due/review`)}${kpiCard('Reference standards',M.standards,`${M.standardsDue} due within 60d`)}${kpiCard('As-found OOT cases',ootEq.length,'Retrospective impact assessment')}${kpiCard('Unacceptable MSA',M.badMsa,'Hard readiness concern')}${kpiCard('Traceability','NMI / accredited','Reference-standard chain')}</div><div class="grid section-grid equal">${section('Gage R&R / MSA register',`<div class="table-wrap"><table><thead><tr><th>Study</th><th>Method / equipment</th><th>Repeatability</th><th>Reproducibility</th><th>Total Gage R&R</th><th>ndc</th><th>Status</th></tr></thead><tbody>${msa.map(x=>`<tr><td>${x.id}<div class="small muted">${fmtDate(x.date)}</div></td><td><span class="link mono" data-entity="method" data-id="${x.methodId}">${x.methodId}</span><div class="small muted">${x.equipmentId}</div></td><td>${x.repeatabilityPct}%</td><td>${x.reproducibilityPct}%</td><td><strong>${x.totalGrrPct}%</strong></td><td>${x.ndc}</td><td>${pill(x.status)}</td></tr>`).join('')}</tbody></table></div>`,'MSA interpretation is a prototype policy and should be configured to the organisation’s approved MSA procedure')}${section('Reference standards',`<div class="list">${state.referenceStandards.map(s=>`<div class="list-row"><div><strong>${s.id} · ${esc(s.name)}</strong><small>${esc(s.traceability)} · ${s.uncertainty} · due ${fmtDate(s.dueDate)}</small></div>${pill(new Date(s.dueDate)<new Date(DEMO_NOW.getTime()+60*86400000)?'Due Soon':s.status)}</div>`).join('')}</div>`,'Expired linked reference standards can block measurement-method readiness')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Measurement uncertainty budgets',`<div class="table-wrap"><table><thead><tr><th>Budget</th><th>Method</th><th>Measurand</th><th>Expanded U</th><th>References</th><th>Status</th><th>Review due</th></tr></thead><tbody>${state.uncertaintyBudgets.map(u=>`<tr><td>${u.id}</td><td>${u.methodId}</td><td>${esc(u.measurand)} (${u.unit})</td><td><strong>${u.expandedUncertainty} ${u.unit}</strong></td><td>${(u.referenceStandardIds||[]).join(', ')||'—'}</td><td>${pill(u.status)}</td><td>${fmtDate(u.reviewDue)}</td></tr>`).join('')}</tbody></table></div>`,'Unacceptable MSA, unreleased uncertainty or expired reference traceability can block method readiness')}${section('As-found OOT impact analysis',`<div class="list">${ootEq.map(id=>{const I=metrologyImpactAnalysis(state,id),eq=state.equipment.find(e=>e.id===id);return`<div class="list-row"><div><strong>${id} · ${esc(eq?.name||'')}</strong><small>${esc(I.oot?.asFound||'')} · ${I.runs.length} potentially impacted historical runs · ${I.requirements.length} linked requirements</small></div><button class="btn small primary" data-act="metrology-impact" data-id="${id}">Assess impact</button></div>`}).join('')||'<div class="empty">No as-found out-of-tolerance history detected.</div>'}</div>`,'The impact interval is traced back to prior calibration and affected test evidence')}</div>`;}
function renderMaterials(){ensureAdvancedState(state);const I=inventorySummary(state),rows=[...state.inventoryItems].sort((a,b)=>a.type.localeCompare(b.type)||a.id.localeCompare(b.id));return pageHead('Fixtures, Consumables & Spares','Treat test fixtures, consumables and critical spares as capacity/readiness constraints with reorder lead time and test-method compatibility',`<button class="btn" data-act="materials-export">⇩ Inventory CSV</button><button class="btn primary" data-act="new-inventory-item">＋ Item</button>`)+`<div class="grid kpi visual-kpis">${kpiCard('Inventory items',I.items,'Fixtures + consumables + spares')}${kpiCard('Stockouts',I.stockout,'Immediate operational risk')}${kpiCard('At / below reorder',I.reorder,'Procurement attention')}${kpiCard('Test legs blocked',I.blockedLegs,'Material / fixture readiness')}${kpiCard('Inventory value',currency(state,I.value,true),'On-hand value')}${kpiCard('Reservations',state.inventoryReservations.filter(r=>r.status==='Reserved').length,'Allocated to future test legs')}</div><div class="grid section-grid equal">${section('Inventory & fixture register',`<div class="table-wrap"><table><thead><tr><th>Item</th><th>Type</th><th>On hand / reorder</th><th>Lead time</th><th>Compatible methods</th><th>Location</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(i=>`<tr><td><strong>${i.id}</strong><div class="small muted">${esc(i.name)}</div></td><td>${pill(i.type)}</td><td><strong>${i.onHand}</strong> / ${i.reorderPoint}</td><td>${i.leadTimeDays}d</td><td>${(i.compatibleMethodIds||[]).join(', ')||'General'}</td><td>${esc(i.location)}</td><td>${pill(i.status)}</td><td><button class="btn small" data-act="inventory-adjust" data-id="${i.id}">Adjust / reorder</button></td></tr>`).join('')}</tbody></table></div>`,'Planner readiness evaluates required items for each test leg')}${section('Blocked / threatened test demand',`<div class="list">${I.blocked.slice(0,15).map(l=>{const r=inventoryReadiness(state,l);return`<div class="list-row"><div><strong>${l.id} · ${esc(l.name)}</strong><small>${l.programmeId} · ${esc(r.reason)}</small></div><button class="btn small" data-act="material-leg-detail" data-id="${l.id}">Open readiness</button></div>`}).join('')||'<div class="empty">No test legs are currently blocked by fixture/material availability.</div>'}</div>`,'The same shortages appear in planning explanations')}</div>`;}

function renderExternal(){ensureAdvancedState(state);const X=externalSummary(state),candidates=state.legs.filter(l=>!['Completed','Cancelled','Failed'].includes(l.status)&&!l.externalLabId).map(l=>({l,alts:externalAlternatives(state,l.id)})).filter(x=>x.alts.length).slice(0,15);return pageHead('External Laboratory / Supplier Testing','Use approved external laboratories as a controlled capacity alternative with accreditation scope, quote, logistics, turnaround, evidence intake and review',`<button class="btn" data-act="new-external-lab">＋ External Lab</button><button class="btn primary" data-act="external-candidate">Find Outsourcing Options</button>`)+`<div class="grid kpi visual-kpis">${kpiCard('External laboratories',X.labs,`${X.approved} approved`)}${kpiCard('Open external jobs',X.openJobs,'Quote / ship / execute / evidence')}${kpiCard('Committed external spend',currency(state,X.spend,true),'Current demo jobs')}${kpiCard('Late external jobs',X.late,'Supplier delivery risk')}${kpiCard('Accreditation control','Scope-aware','Category / accreditation visible')}${kpiCard('Planner alternative','Internal ↔ External','Capacity and cost trade-off')}</div><div class="grid section-grid equal">${section('Approved / conditional laboratory panel',`<div class="list">${state.externalLabs.map(l=>`<div class="list-row"><div><strong>${l.id} · ${esc(l.name)}</strong><small>${l.categories.join(', ')} · ${esc(l.accreditation)} · ${l.turnaroundDays}d standard turnaround · ${l.onTimePct}% on-time</small></div>${pill(l.status)}</div>`).join('')}</div>`,'Production version would verify accreditation scope documents and supplier status')}${section('External jobs & evidence return',`<div class="list">${state.externalJobs.map(j=>{const l=state.externalLabs.find(x=>x.id===j.labId),leg=state.legs.find(x=>x.id===j.legId);return`<div class="list-row"><div><strong>${j.id} · ${leg?.id||j.legId}</strong><small>${esc(l?.name||j.labId)} · ${currency(state,j.quoteCost,true)} · return ${fmtDate(j.expectedReturn)} · evidence ${j.evidenceStatus}</small></div>${pill(j.status)}</div>`}).join('')||'<div class="empty">No external jobs.</div>'}</div>`,'External evidence is reviewed before requirement verification')}</div><div style="margin-top:14px">${section('Internal capacity alternatives',`<div class="table-wrap"><table><thead><tr><th>Test leg</th><th>Method</th><th>Current state</th><th>Best external alternative</th><th>Turnaround</th><th>Cost</th><th>Score</th><th>Action</th></tr></thead><tbody>${candidates.map(({l,alts})=>{const a=alts[0];return`<tr><td>${l.id}<div class="small muted">${l.programmeId}</div></td><td>${l.methodId}</td><td>${pill(l.status)}</td><td>${esc(a.lab.name)}</td><td>${a.lab.turnaroundDays}d</td><td>${currency(state,a.cost,true)}</td><td>${a.score}/100</td><td><button class="btn small primary" data-act="external-options" data-id="${l.id}">Compare / outsource</button></td></tr>`}).join('')}</tbody></table></div>`,'Use external capacity deliberately when it improves delivery, competency coverage or asset bottlenecks')}</div>`;}

function renderKnowledge(){ensureAdvancedState(state);const pid=state.settings.knowledgeProgramme||state.programmes[0]?.id||'',rows=programmeSimilarity(state,pid),rec=knowledgeRecommendation(state,{programmeId:pid});return pageHead('Validation Knowledge & Similarity Graph','Reuse historical programmes as structured knowledge: test sequence, methods, DUT volume, time, issues, cost and resource patterns',`<button class="btn" data-route-jump="builder">Open Programme Builder</button><button class="btn primary" data-act="knowledge-use" data-id="${rec?.sourceProgrammeId||''}">Use Best-Match Template</button>`)+`<div class="project-plan-bar card"><label>Target programme<select id="knowledgeProgramme">${state.programmes.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select></label><div class="project-plan-meta"><strong>Similarity uses method + category overlap and product-family signal</strong><span>The recommendation links back to real historical programmes rather than opaque AI output.</span></div></div>${rec?`<div class="callout"><strong>Best reusable knowledge: ${rec.sourceProgrammeId} · ${esc(rec.sourceProject)} · ${rec.similarity}% similarity</strong><div>${rec.typicalLegs} test legs · ${rec.typicalDuts} DUTs · median method time ${rec.medianMethodHours}h · methods ${rec.recommendedMethods.join(', ')}</div><div class="small muted">Top lessons: ${rec.topLessons.map(x=>`${x.name} (${x.count})`).join(' · ')||'no recurring issue family'}</div></div>`:''}<div style="margin-top:14px">${section('Similarity ranking',`<div class="table-wrap"><table><thead><tr><th>Rank</th><th>Programme</th><th>Similarity</th><th>Method overlap</th><th>Category overlap</th><th>Historical signal</th><th>Action</th></tr></thead><tbody>${rows.slice(0,12).map((r,i)=>{const issues=state.issues.filter(x=>x.programmeId===r.programme.id).length,runs=state.testRuns.filter(x=>x.programmeId===r.programme.id).length;return`<tr><td>${i+1}</td><td><span class="link mono" data-entity="programme" data-id="${r.programme.id}">${r.programme.id}</span><div class="small muted">${esc(r.programme.project)}</div></td><td><strong>${r.score}%</strong><div class="progress"><span style="width:${r.score}%"></span></div></td><td>${r.methodOverlap}%</td><td>${r.categoryOverlap}%</td><td>${runs} runs · ${issues} issues</td><td><button class="btn small" data-act="knowledge-use" data-id="${r.programme.id}">Build from this</button></td></tr>`}).join('')}</tbody></table></div>`,'This also supports potential-project estimation when the exact validation plan is not known')}</div>`;}

function qualityDetailModal(id){const q=state.qualityEvents.find(x=>x.id===id);if(!q)return;const issue=state.issues.find(i=>i.id===q.sourceId),capas=state.capaActions.filter(c=>c.qualityEventId===id),leg=state.legs.find(l=>l.id===q.legId);openModal(`<h2>${q.id} · ${esc(q.type)}</h2><div class="actions"><button class="btn" data-act="quality-edit" data-id="${id}">Edit Investigation / MRB</button><button class="btn" data-act="quality-advance" data-id="${id}">Advance Stage</button><button class="btn primary" data-act="quality-add-capa" data-id="${id}">＋ CAPA</button></div><div class="detail-grid"><div class="detail"><small>Severity</small><strong>${q.severity}</strong></div><div class="detail"><small>Status</small><strong>${q.status}</strong></div><div class="detail"><small>Programme / leg</small><strong>${q.programmeId} · ${q.legId||'programme'}</strong></div><div class="detail"><small>DUTs</small><strong>${(q.dutIds||[]).join(', ')||'—'}</strong></div><div class="detail"><small>Owner</small><strong>${esc(q.owner)}</strong></div><div class="detail"><small>Due</small><strong>${fmtDate(q.dueDate)}</strong></div></div><h3>Containment</h3><div class="callout">${esc(q.containment)}</div><h3>Investigation / root cause</h3><div class="callout"><strong>${esc(q.investigationMethod)}:</strong> ${esc(q.rootCause)}</div><h3>MRB / disposition</h3><div class="callout">${esc(q.disposition)}</div>${issue?`<h3>Originating issue</h3><div class="callout warning"><strong>${issue.id} · ${esc(issue.issueType)}</strong><div>${esc(issue.description)}</div><small>${issue.delayHours||0}h delay · ${issue.severity}</small></div>`:''}<h3>CAPA actions</h3><div class="list">${capas.map(c=>`<div class="list-row"><div><strong>${c.id} · ${esc(c.description)}</strong><small>${esc(c.owner)} · due ${fmtDate(c.dueDate)} · effectiveness ${c.effectivenessStatus}</small></div><div class="actions">${pill(c.status)}${c.effectivenessStatus!=='Effective'?`<button class="btn small" data-act="capa-verify" data-id="${c.id}">Verify effective</button>`:''}</div></div>`).join('')||'<div class="empty">No CAPA linked yet.</div>'}</div><h3>Execution impact</h3><div class="callout ${['Major','Critical'].includes(q.severity)&&q.status!=='Closed'?'warning':''}">${leg&&['Major','Critical'].includes(q.severity)&&q.status!=='Closed'?`This open ${q.severity.toLowerCase()} event is an execution/planning readiness hold for ${leg.id}.`:'No hard execution hold from this event.'}</div>`);wireModalActions();}
function newQualityModal(){openModal(`<h2>New Quality Event</h2><div class="modal-grid"><div class="field"><label>Type</label><select id="qeType"><option>Deviation</option><option>NCR</option><option>OOS</option><option>OOT</option><option>Specification Deviation</option><option>MRB</option></select></div><div class="field"><label>Severity</label><select id="qeSeverity"><option>Minor</option><option>Major</option><option>Critical</option><option>Observation</option></select></div><div class="field"><label>Programme</label><select id="qeProg">${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select></div><div class="field"><label>Test leg</label><select id="qeLeg"><option value="">Programme level</option>${state.legs.map(l=>`<option value="${l.id}">${l.id} · ${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Owner</label><input id="qeOwner" value="${esc(state.settings.actor||'Demo Lab Manager')}"></div><div class="field"><label>Due date</label><input id="qeDue" type="date" value="${dayISO(7).slice(0,10)}"></div></div><label>Description / containment<textarea id="qeDesc">Contain affected work, preserve evidence and investigate before disposition.</textarea></label><button id="saveQE" class="btn primary">Create Quality Event</button>`);document.getElementById('saveQE').onclick=async()=>{const legId=document.getElementById('qeLeg').value,prog=legId?state.legs.find(l=>l.id===legId)?.programmeId:document.getElementById('qeProg').value,q={id:`QE-${String(state.qualityEvents.length+1).padStart(3,'0')}`,type:document.getElementById('qeType').value,sourceType:'Manual',sourceId:'',programmeId:prog,legId,dutIds:(state.legs.find(l=>l.id===legId)?.dutIds||[]).slice(0,3),severity:document.getElementById('qeSeverity').value,status:'Containment',detectedAt:new Date().toISOString(),owner:document.getElementById('qeOwner').value,containment:document.getElementById('qeDesc').value,investigationMethod:'5 Why',rootCause:'Under investigation',disposition:'Hold pending review',dueDate:new Date(document.getElementById('qeDue').value+'T17:00:00Z').toISOString(),effectivenessStatus:'Pending'};state.qualityEvents.push(q);state.audit.push(audit('Quality event created',q.id,'',`${q.type} · ${q.severity}`));state.settings.planDirty=true;await persist();closeModal();render();toast(`${q.id} created; affected test readiness updated.`)};}
function qualityCapaModal(id){const q=state.qualityEvents.find(x=>x.id===id);if(!q)return;openModal(`<h2>Add CAPA · ${id}</h2><label>Corrective / preventive action<textarea id="capaDesc">Update controlled method / fixture readiness gate and verify effectiveness on the next five applicable runs.</textarea></label><label>Owner<select id="capaOwner">${state.staff.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></label><button id="saveCAPA" class="btn primary">Create CAPA</button>`);document.getElementById('saveCAPA').onclick=async()=>{const c=addCapa(state,id,document.getElementById('capaDesc').value,document.getElementById('capaOwner').value);state.audit.push(audit('CAPA created',c.id,'',id));await persist();closeModal();render();toast(`${c.id} linked to ${id}.`)};}
function custodyDetailModal(id){const C=currentCustody(state,id),d=state.duts.find(x=>x.id===id);openModal(`<h2>${id} · Custody History</h2><div class="callout"><strong>${d?.serialNumber} · ${C.status}</strong><div>Current location: ${esc(state.sampleLocations.find(l=>l.id===C.location)?.name||C.location)}</div></div><div class="timeline">${C.events.map(e=>`<div class="audit-item"><strong>${esc(e.type)} · ${esc(e.from)} → ${esc(e.to)}</strong><span>${fmtDate(e.timestamp,true)} · ${esc(e.actor)}</span><small>${esc(e.condition)}</small></div>`).join('')}</div><div class="actions"><button class="btn primary" data-act="custody-move" data-id="${id}">Move / disposition</button></div>`);wireModalActions();}
function custodyMoveModal(id){const d=state.duts.find(x=>x.id===id);if(!d)return;openModal(`<h2>Move / Disposition · ${id}</h2><div class="modal-grid"><div class="field"><label>Destination</label><select id="cTo">${state.sampleLocations.map(l=>`<option value="${l.id}">${l.id} · ${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Event type</label><select id="cType"><option>Moved</option><option>Released</option><option>Quarantined</option><option>Issued to Test</option><option>Returned</option><option>Retained</option><option>Disposed</option></select></div></div><label>Condition / note<textarea id="cNote">Identity confirmed; no abnormal condition observed.</textarea></label><button id="saveCustody" class="btn primary">Record Custody Event</button>`);document.getElementById('saveCustody').onclick=async()=>{const ev=moveDut(state,id,document.getElementById('cTo').value,document.getElementById('cType').value,state.settings.actor,document.getElementById('cNote').value);state.audit.push(audit('DUT custody changed',id,ev.from,ev.to));state.settings.planDirty=true;await persist();closeModal();render();toast(`${id} moved to ${ev.to}; readiness recalculated.`)};}
function guidedOpenModal(id){const ex=state.guidedExecutions.find(x=>x.id===id);if(!ex)return;const l=state.legs.find(x=>x.id===ex.legId),tpl=state.lesTemplates.find(x=>x.id===ex.templateId),R=ex.status==='Awaiting Review'?guidedReviewReadiness(state,id):null;openModal(`<h2>${ex.id} · Guided Execution</h2><div class="callout"><strong>${l?.id} · ${esc(l?.name)}</strong><div>${l?.methodId} · ${(l?.dutIds||[]).length} DUTs · ${ex.status} · review ${ex.reviewStatus||'Pending'}</div></div>${R?`<div class="callout ${R.ok?'success':'warning'}"><strong>${R.ok?'Ready for controlled review':'Review blocked'}</strong><div>${R.ok?'All mandatory steps complete and execution exceptions are dispositioned.':esc(R.reasons.join(' '))}</div></div>`:''}<div class="les-steps">${tpl.steps.map(s=>{const st=ex.stepStates.find(x=>x.stepId===s.id);return`<div class="les-step ${st?.status==='Completed'?'done':''}"><div><strong>${s.sequence}. ${esc(s.title)}</strong><small>${esc(s.instruction)} · ${s.mandatory?'mandatory':'optional'}${st?.evidence?` · evidence ${esc(st.evidence)}`:''}${st?.exception?` · exception: ${esc(st.exception)}`:''}</small></div>${st?.status==='Completed'?pill('Completed'):`<button class="btn small primary" data-act="guided-step" data-id="${ex.id}" data-step="${s.id}">Complete step</button>`}</div>`}).join('')}</div>${ex.status==='Awaiting Review'?`<div class="actions"><button class="btn primary" data-act="guided-review" data-id="${ex.id}" ${R?.ok?'':'disabled'}>Review & Approve Execution</button></div>`:''}`);wireModalActions();}
function guidedStepModal(exId,stepId){const ex=state.guidedExecutions.find(x=>x.id===exId),tpl=state.lesTemplates.find(x=>x.id===ex?.templateId),stp=tpl?.steps.find(x=>x.id===stepId);if(!stp)return;openModal(`<h2>${stp.sequence}. ${esc(stp.title)}</h2><p>${esc(stp.instruction)}</p><label>Recorded value / observation<input id="gsVal" value="OK"></label><label>Evidence reference<input id="gsEv" value="${stp.requiresEvidence?'EVID-DEMO-'+Date.now().toString().slice(-5):''}"></label><label>Exception (leave blank when normal)<textarea id="gsEx"></textarea></label><button id="saveStep" class="btn primary">Complete Step</button>`);document.getElementById('saveStep').onclick=async()=>{const exception=document.getElementById('gsEx').value.trim();completeGuidedStep(state,exId,stepId,{value:document.getElementById('gsVal').value,evidence:document.getElementById('gsEv').value,exception});state.audit.push(audit('LES step completed',`${exId}:${stepId}`,'Pending',exception?'Completed with exception':'Completed'));await persist();closeModal();render();toast(exception?'Step completed; quality event created for exception.':'Guided step completed.');};}
function msaModal(){openModal(`<h2>New Gage R&R / MSA Study</h2><div class="modal-grid"><div class="field"><label>Test method</label><select id="msaMethod">${state.methods.filter(m=>m.active).map(m=>`<option value="${m.id}">${m.id} · ${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label>Equipment</label><select id="msaEq">${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Total Gage R&R %</label><input id="msaPct" type="number" step="0.1" min="0" value="9.5"></div><div class="field"><label>Owner</label><input id="msaOwner" value="Priya Shah"></div></div><button id="saveMSA" class="btn primary">Save MSA Study</button>`);document.getElementById('saveMSA').onclick=async()=>{const x=addMsaStudy(state,{methodId:document.getElementById('msaMethod').value,equipmentId:document.getElementById('msaEq').value,totalGrrPct:document.getElementById('msaPct').value,owner:document.getElementById('msaOwner').value});state.audit.push(audit('MSA study added',x.id,'',`${x.methodId} · ${x.totalGrrPct}%`));state.settings.planDirty=true;await persist();closeModal();render();toast(`${x.id}: ${x.status}.`)};}
function inventoryAdjustModal(id){const i=state.inventoryItems.find(x=>x.id===id);if(!i)return;openModal(`<h2>${id} · ${esc(i.name)}</h2><div class="modal-grid"><div class="field"><label>On hand</label><input id="invOn" type="number" min="0" value="${i.onHand}"></div><div class="field"><label>Reorder point</label><input id="invRe" type="number" min="0" value="${i.reorderPoint}"></div><div class="field"><label>Lead time (days)</label><input id="invLead" type="number" min="0" value="${i.leadTimeDays}"></div><div class="field"><label>Unit cost</label><input id="invCost" type="number" min="0" step="0.01" value="${i.unitCost}"></div></div><button id="saveInv" class="btn primary">Save & Recalculate Readiness</button>`);document.getElementById('saveInv').onclick=async()=>{i.onHand=Number(document.getElementById('invOn').value);i.reorderPoint=Number(document.getElementById('invRe').value);i.leadTimeDays=Number(document.getElementById('invLead').value);i.unitCost=Number(document.getElementById('invCost').value);i.status=i.onHand<=0?'Stockout':i.onHand<=i.reorderPoint?'Reorder':'Available';state.audit.push(audit('Inventory item changed',id,'',`${i.onHand} on hand`));state.settings.planDirty=true;await persist();closeModal();render();toast(`${id} updated; planning readiness changed.`)};}
function externalOptionsModal(id){const l=state.legs.find(x=>x.id===id),alts=externalAlternatives(state,id);if(!l)return;openModal(`<h2>${id} · Internal vs External Test Options</h2><div class="callout"><strong>${l.methodId} · ${esc(l.name)}</strong><div>Internal planned: ${fmtDate(l.plannedStart,true)} → ${fmtDate(l.plannedEnd,true)} · equipment ${l.equipmentId||'unassigned'}</div></div><div class="list">${alts.map(a=>`<div class="list-row"><div><strong>${a.lab.id} · ${esc(a.lab.name)}</strong><small>${a.lab.turnaroundDays}d turnaround · ${a.lab.onTimePct}% on-time · ${esc(a.lab.accreditation)} · ${currency(state,a.cost,true)}</small></div><button class="btn small primary" data-act="external-commit" data-id="${id}" data-lab="${a.lab.id}">Outsource</button></div>`).join('')||'<div class="empty">No approved external laboratory covers this method category.</div>'}</div>`);wireModalActions();}
function twinSettingsModal(){openModal(`<h2>Digital Twin Simulation Settings</h2><label>Iterations<input id="twIter" type="number" min="100" max="2000" step="100" value="${state.settings.digitalTwin.iterations||400}"></label><label class="review-check"><input id="twPipe" type="checkbox" ${state.settings.digitalTwin.includePipeline?'checked':''}><span><strong>Include pipeline context in management interpretation</strong><small>Current prototype simulates committed programme dates directly; pipeline remains capacity context.</small></span></label><button id="saveTwin" class="btn primary">Save Simulation Settings</button>`);document.getElementById('saveTwin').onclick=async()=>{state.settings.digitalTwin.iterations=Math.max(100,Math.min(2000,Number(document.getElementById('twIter').value)||400));state.settings.digitalTwin.includePipeline=document.getElementById('twPipe').checked;await persist();closeModal();render();toast('Digital twin settings updated.')};}
async function useKnowledgeTemplate(id){const p=state.programmes.find(x=>x.id===id);if(!p)return;const legs=state.legs.filter(l=>l.programmeId===id).sort((a,b)=>a.sequence-b.sequence);if(state.settings.builderDraft)syncBuilderDesign({create:true});state.settings.currentValidationDesignId='';state.settings.builderDraft=defaultBuilderDraft();const d=state.settings.builderDraft;d.project=p.project;d.customer=p.customer;d.product=p.product;d.revision=p.productRevision||'R1.0';d.priority=p.priority;d.businessPriority=p.businessPriority;d.dueDate=new Date(p.dueDate).toISOString().slice(0,10);d.budget=p.budget||programmeCost(state,id).budget;d.dutCount=Math.max(1,state.duts.filter(x=>x.programmeId===id).length);const map={};d.legs=legs.map((l,i)=>{const bid=`BL-EDIT-${Date.now()}-${i}`;map[l.id]=bid;const m=state.methods.find(x=>x.id===l.methodId),dev=l.developmentTaskId?state.devTasks.find(x=>x.id===l.developmentTaskId):null;return{id:bid,kind:m?.active?'existing':'custom',methodId:m?.active?l.methodId:undefined,tempId:m?.active?undefined:l.methodId,name:m?.name||l.name,legName:l.name,category:m?.category||'Other',equipmentType:m?.equipmentType||state.equipment[0]?.type,skill:m?.requiredSkills?.[0]||'General',executionHours:m?.executionHours||8,setupHours:m?.setupHours||4,teardownHours:m?.teardownHours||2,analysisHours:m?.analysisHours||4,devDays:dev?.elapsedDays||7,engineeringHours:dev?.estimatedEngineeringHours||40,technicianHours:dev?.estimatedTechnicianHours||16,dutCount:l.dutIds?.length||d.dutCount,populationMode:l.populationMode||'Continue',dependencyMode:i===0?'Start':'Custom',dependsOn:[],staffId:l.preferredStaffId||l.staffId||'',staffPolicy:l.staffPolicy||'Auto',sampleReadyOffset:0,sourceLegId:l.id,mainLegNo:Number(l.validationLegNo)||Number(l.sequence)||i+1,stepNo:Number(l.validationStepNo)||1,phase:l.validationSubLeg?'branch':'common',branchKey:l.validationBranchPath||l.validationSubLeg||l.subLeg||'',branchPath:l.validationBranchPath||l.validationSubLeg||l.subLeg||'',branchGroup:l.parallelGroup||'',mergeFrom:''};});for(let i=0;i<legs.length;i++){d.legs[i].dependsOn=(legs[i].predecessorIds||[]).map(x=>map[x]).filter(Boolean);if(i>0&&!d.legs[i].dependsOn.length)d.legs[i].dependsOn=[d.legs[i-1].id];}d.editProgrammeId=id;state.audit.push(audit('Programme loaded into validation designer','Programme Builder','',id));await persist();go('builder');toast(`${id} loaded as an editable validation plan. Creating will produce a new revision/demo programme; existing evidence is not overwritten.`)}


function qualityEditModal(id){const q=state.qualityEvents.find(x=>x.id===id);if(!q)return;openModal(`<h2>${q.id} · Investigation / MRB</h2><div class="modal-grid"><div class="field"><label>Severity</label><select id="qeEditSeverity">${['Observation','Minor','Major','Critical'].map(x=>`<option ${q.severity===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Investigation method</label><select id="qeEditMethod">${['5 Why','Fishbone','Is / Is Not','8D','Fault tree','Technical review'].map(x=>`<option ${q.investigationMethod===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Owner</label><input id="qeEditOwner" value="${esc(q.owner)}"></div><div class="field"><label>Due date</label><input id="qeEditDue" type="date" value="${new Date(q.dueDate).toISOString().slice(0,10)}"></div></div><label>Containment<textarea id="qeEditContain">${esc(q.containment)}</textarea></label><label>Confirmed / suspected root cause<textarea id="qeEditRoot">${esc(q.rootCause)}</textarea></label><label>MRB / disposition<select id="qeEditDisp"><option ${q.disposition==='Hold pending review'?'selected':''}>Hold pending review</option><option ${q.disposition==='Rework / retest'?'selected':''}>Rework / retest</option><option ${q.disposition==='Use as-is with justification'?'selected':''}>Use as-is with justification</option><option ${q.disposition==='Scrap / dispose'?'selected':''}>Scrap / dispose</option><option ${q.disposition==='Return to supplier'?'selected':''}>Return to supplier</option></select></label><button id="saveQeEdit" class="btn primary">Save Investigation / Disposition</button>`);document.getElementById('saveQeEdit').onclick=async()=>{const old=JSON.stringify({severity:q.severity,rootCause:q.rootCause,disposition:q.disposition});q.severity=document.getElementById('qeEditSeverity').value;q.investigationMethod=document.getElementById('qeEditMethod').value;q.owner=document.getElementById('qeEditOwner').value.trim();q.dueDate=new Date(document.getElementById('qeEditDue').value+'T17:00:00Z').toISOString();q.containment=document.getElementById('qeEditContain').value.trim();q.rootCause=document.getElementById('qeEditRoot').value.trim();q.disposition=document.getElementById('qeEditDisp').value;state.audit.push(audit('Quality investigation updated',q.id,old,JSON.stringify({severity:q.severity,rootCause:q.rootCause,disposition:q.disposition})));state.settings.planDirty=true;await persist();closeModal();render();toast(`${q.id} investigation and MRB disposition updated.`)};}
function verifyCapa(id){const c=state.capaActions.find(x=>x.id===id);if(!c)return;openModal(`<h2>CAPA Effectiveness Verification · ${c.id}</h2><div class="callout"><strong>${esc(c.effectivenessCriteria||'Defined effectiveness criterion')}</strong><p>Closing a CAPA requires evidence that the effectiveness criterion was actually checked.</p></div><div class="field"><label>Verification result</label><select id="capaResult"><option>Effective</option><option>Not Effective</option></select></div><div class="field"><label>Effectiveness evidence</label><textarea id="capaEvidence" placeholder="e.g. next 5 runs reviewed: no recurrence; audit record; capability study; trend chart reference..."></textarea></div><div class="field"><label>Verified by</label><select id="capaVerifier">${state.staff.map(s=>`<option value="${s.name}">${esc(s.name)} · ${esc(s.role)}</option>`).join('')}</select></div><button id="confirmCapa" class="btn primary">Record Effectiveness Review</button>`);document.getElementById('confirmCapa').onclick=async()=>{const result=document.getElementById('capaResult').value,evidence=document.getElementById('capaEvidence').value.trim(),verifier=document.getElementById('capaVerifier').value;if(!evidence)return toast('Effectiveness evidence is required.');c.effectivenessEvidence=[...(c.effectivenessEvidence||[]),{result,evidence,verifiedBy:verifier,timestamp:new Date().toISOString()}];c.verifiedAt=new Date().toISOString();c.effectivenessStatus=result;c.status=result==='Effective'?'Closed':'In Progress';const q=state.qualityEvents.find(x=>x.id===c.qualityEventId),all=q&&state.capaActions.filter(x=>x.qualityEventId===q.id).every(x=>x.effectivenessStatus==='Effective');if(q){if(all&&['CAPA','CAPA Verification'].includes(q.status)){q.status='CAPA Verification';q.effectivenessStatus='Effective';}if(result==='Not Effective'){q.status='CAPA';q.effectivenessStatus='Not Effective';}}state.audit.push(audit('CAPA effectiveness evidence recorded',id,'Pending',`${result} · ${evidence}`));state.settings.planDirty=true;await persist();closeModal();render();toast(`${id}: ${result}. ${all?'Quality event is ready for evidence-backed closure.':'Further action remains open.'}`)}}

function custodySplitModal(id){const g=state.sampleGroups.find(x=>x.id===id);if(!g)return;openModal(`<h2>Split population · ${g.id}</h2><p class="small muted">Choose the DUTs that form the new child population. The remaining DUTs stay in the source group; individual custody locations do not change.</p><label>New group name<input id="sgName" value="${esc(g.name)} · branch"></label><div class="check-grid">${(g.memberIds||[]).map(did=>{const d=state.duts.find(x=>x.id===did);return`<label class="review-check"><input class="sgDut" type="checkbox" value="${did}"><span><strong>${did}</strong><small>${d?.serialNumber||''} · ${currentCustody(state,did).status}</small></span></label>`}).join('')}</div><button id="saveSplit" class="btn primary">Create Split Population</button>`);document.getElementById('saveSplit').onclick=async()=>{const ids=[...modalBody.querySelectorAll('.sgDut:checked')].map(x=>x.value),ng=splitSampleGroup(state,id,ids,document.getElementById('sgName').value.trim()||'Split population');if(!ng)return toast('Select at least one but not all DUTs.');state.audit.push(audit('DUT population split',id,'',ng.id));await persist();closeModal();render();toast(`${ng.id} created with ${ng.memberIds.length} DUTs.`)};}
function custodyMergeModal(){const pid=state.settings.custodyProgramme||'',groups=state.sampleGroups.filter(g=>g.status==='Active'&&(!pid||g.programmeId===pid));openModal(`<h2>Merge validation populations</h2><p class="small muted">Select two or more active groups from the same programme. A new merged population is created and source groups remain in genealogy history.</p><label>Merged group name<input id="mergeName" value="Merged validation population"></label><div class="check-grid">${groups.map(g=>`<label class="review-check"><input class="mgGroup" type="checkbox" value="${g.id}"><span><strong>${g.id} · ${esc(g.name)}</strong><small>${g.programmeId} · ${(g.memberIds||[]).length} DUTs</small></span></label>`).join('')}</div><button id="saveMerge" class="btn primary">Merge Groups</button>`);document.getElementById('saveMerge').onclick=async()=>{const ids=[...modalBody.querySelectorAll('.mgGroup:checked')].map(x=>x.value),g=mergeSampleGroups(state,ids,document.getElementById('mergeName').value.trim()||'Merged population');if(!g)return toast('Select at least two active groups from one programme.');state.audit.push(audit('DUT populations merged',g.id,ids.join(', '),`${g.memberIds.length} DUTs`));await persist();closeModal();render();toast(`${g.id} created from ${ids.length} groups.`)};}
function guidedReviewModal(id){const ex=state.guidedExecutions.find(x=>x.id===id),R=guidedReviewReadiness(state,id);if(!ex)return;openModal(`<h2>${id} · Review by Exception</h2><div class="callout ${R.ok?'success':'warning'}"><strong>${R.ok?'Execution ready for approval':'Approval blocked'}</strong><div>${R.ok?'All mandatory LES steps are complete and execution deviations are dispositioned.':esc(R.reasons.join(' '))}</div></div><label>Reviewer<select id="grReviewer">${state.staff.filter(s=>/Engineer|Quality|Manager/.test(s.role||'')).map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.role)}</option>`).join('')}</select></label><button id="approveGuided" class="btn primary" ${R.ok?'':'disabled'}>Approve Controlled Execution</button>`);const btn=document.getElementById('approveGuided');if(btn)btn.onclick=async()=>{const out=approveGuidedExecution(state,id,document.getElementById('grReviewer').value);if(!out.ok)return toast(out.reasons.join(' '));state.audit.push(audit('Guided execution approved',id,'Awaiting Review','Approved'));await persist();closeModal();render();toast(`${id} approved; test lifecycle updated.`)};}
function metrologyImpactModal(eqId){const I=metrologyImpactAnalysis(state,eqId),eq=state.equipment.find(e=>e.id===eqId);openModal(`<h2>${eqId} · As-found OOT Impact Analysis</h2><div class="callout warning"><strong>${esc(I.oot?.asFound||'No OOT record')}</strong><div>${esc(I.decision)}</div></div>${I.oot?`<div class="detail-grid"><div class="detail"><small>OOT calibration</small><strong>${I.oot.id}</strong></div><div class="detail"><small>Calibration date</small><strong>${fmtDate(I.oot.calibrationDate)}</strong></div><div class="detail"><small>Prior calibration</small><strong>${I.previousCalibration?.id||'None'}</strong></div><div class="detail"><small>Impacted runs</small><strong>${I.runs.length}</strong></div></div><h3>Potentially affected evidence</h3><div class="table-wrap"><table><thead><tr><th>Run</th><th>Leg / programme</th><th>Date</th><th>Outcome</th><th>Requirements</th></tr></thead><tbody>${I.runs.map(r=>{const l=state.legs.find(x=>x.id===r.legId);return`<tr><td>${r.id}</td><td>${r.legId} · ${r.programmeId}</td><td>${fmtDate(r.actualEnd,true)}</td><td>${pill(r.outcome)}</td><td>${(l?.requirementIds||[]).join(', ')||'—'}</td></tr>`}).join('')||'<tr><td colspan="5">No runs in impact interval.</td></tr>'}</tbody></table></div><h3>Linked requirements</h3><p>${I.requirements.map(r=>r.id).join(', ')||'None'}</p>`:''}`);}

init().catch(err=>{console.error(err);main.innerHTML=`<div class="callout danger"><strong>Application failed to initialise.</strong><div>${esc(err.message)}</div></div>`});
